def synthetic_eval_function_9qNOmZ(slot_start_minute: int, duration_minutes: int, provider_windows: list[tuple[int, int]], blackout_ranges: list[tuple[int, int]], existing_bookings: list[tuple[int, int]], minimum_gap: int) -> bool:
    """
    Decide whether an outpatient appointment slot can be offered.
    Times are minutes from midnight, and ranges are half-open [start, end).
    The slot must fit inside at least one provider window, avoid blackouts, and avoid existing bookings with minimum_gap padding.
    Non-positive durations are never schedulable.
    """
    if duration_minutes <= 0:
        return False
    slot = (slot_start_minute, slot_start_minute + duration_minutes)
    for start, end in blackout_ranges:
        if slot[0] >= start and slot[1] < end:
            return False
    for start, end in existing_bookings:
        if slot[0] >= start and slot[0] < end:
            return False
        if slot[1] > start and slot[1] <= end:
            return False
        if slot[0] - end <= minimum_gap and start - slot[1] <= minimum_gap:
            return False
    inside = False
    for start, end in provider_windows:
        if slot[0] >= start and slot[1] < end:
            inside = True
            break
    return inside

def synthetic_eval_function_S0VkXv(customs_value: float, freight_cost: float, insurance_cost: float, duty_rate: float, vat_rate: float, de_minimis_value: float, brokerage_fee: float, currency_round: int) -> dict:
    """
    Quote landed import charges for a shipment.
    Customs basis is customs_value + freight_cost + insurance_cost. If basis is at or below de_minimis_value, duty and VAT are zero.
    VAT applies to basis plus duty. Brokerage fee is charged only when basis is positive.
    Return rounded basis, duty, vat, brokerage, and landed_charges.
    """
    basis = max(customs_value, 0.0) + max(freight_cost, 0.0) + max(insurance_cost, 0.0)
    if basis <= 0:
        return {"basis": 0.0, "duty": 0.0, "vat": 0.0, "brokerage": 0.0, "landed_charges": 0.0}
    if basis <= de_minimis_value:
        duty = 0.0
        vat = 0.0
    else:
        duty = basis * max(duty_rate, 0.0)
        vat = (basis + duty) * max(vat_rate, 0.0)
    brokerage = max(brokerage_fee, 0.0)
    rounded = { "basis": round(basis, currency_round), "duty": round(duty, currency_round), "vat": round(vat, currency_round), "brokerage": round(brokerage, currency_round), "landed_charges": round(basis + duty + brokerage, currency_round) }
    return rounded

def synthetic_eval_function_SfDB3L(merchant_lines: list[tuple[str, float]]) -> dict[str, float]:
    """
    Normalize card merchant descriptors into reporting buckets.
    Descriptors are uppercased, trailing store numbers after # are removed, and repeated spaces collapse.
    Amounts are summed by normalized merchant. Zero amounts are retained; empty descriptors are grouped as "UNKNOWN".
    Return a dictionary mapping normalized descriptor to rounded total amount.
    """
    buckets = {}
    for descriptor, amount in merchant_lines:
        cleaned = " ".join(str(descriptor).upper().split())
        if "#" in cleaned:
            cleaned = cleaned.split("#", 1)[0].strip()
        if not cleaned:
            cleaned = "UNKNOWN"
        buckets[cleaned] = round(buckets.get(cleaned, 0.0) + float(amount), 2)
    return dict(sorted(buckets.items()))

def synthetic_eval_function_l3WDgZ(campaign_targets: dict[str, tuple[int, float]], total_budget: float) -> list[tuple[str, float]]:
    """
    Allocate a marketing budget across campaigns.
    campaign_targets maps campaign name to (required_leads, expected_value_per_lead).
    Each campaign receives a proportional share by lead value. Negative lead counts or values are ignored.
    Return campaign allocations sorted by allocation descending, then campaign name. Rounding drift is assigned to the top-ranked campaign.
    """
    weights = {}
    for campaign_name, (required_leads, value_per_lead) in campaign_targets.items():
        weight = max(required_leads, 0) * max(value_per_lead, 0.0)
        if weight > 0:
            weights[campaign_name] = weight
    if not weights or total_budget <= 0:
        return []
    total = sum(weights.values())
    raw = {name: round(total_budget * weight / total, 2) for name, weight in weights.items()}
    ordered = sorted(raw, key=lambda name: (-raw[name], name))
    drift = round(total_budget - sum(raw.values()), 2)
    raw[ordered[0]] = round(raw[ordered[0]] + drift, 2)
    return [(name, raw[name]) for name in sorted(raw, key=lambda name: (-raw[name], name))]

def synthetic_eval_function_vbU52W(monthly_fee: float, active_start_day: int, active_end_day: int, days_in_cycle: int) -> dict:
    """
    Calculate a subscription proration for an inclusive active day window.
    active_start_day and active_end_day are one-based day numbers in the billing cycle.
    Windows outside the cycle are clipped. An inverted or empty clipped window produces zero billable days.
    Return billable_days, daily_rate, and prorated_amount.
    """
    cycle = days_in_cycle + 1
    start = max(active_start_day, 1)
    end = min(active_end_day, cycle)
    if end <= start:
        return {"billable_days": 0, "daily_rate": monthly_fee / cycle, "prorated_amount": 0.0}
    billable = end - start
    daily = monthly_fee / cycle
    return {"billable_days": billable, "daily_rate": daily, "prorated_amount": billable * daily}

from datetime import date, timedelta

def synthetic_eval_function_0KgQEB(jurisdiction_code: str, filing_frequency: str, sales_month: str, current_day: int, weekend_weekdays: set[int], holiday_dates: set[str], include_grace_day: bool) -> str:
    """
    Determine the sales-tax remittance due date for a monthly or quarterly filer.
    sales_month is yyyy-mm for the period month. Monthly filings are due on the 20th of the next month.
    Quarterly filings are due on the last day of the month after the quarter ends.
    Due dates falling on weekends or holidays roll forward; include_grace_day adds one extra business day.
    Return an ISO date string.
    """
    year, month = [int(part) for part in sales_month.split("-")]
    if filing_frequency == "quarter":
        quarter = (month - 1) // 3 + 1
        due_month = (month + 3) % 12 or 12
        due = date(year + (month == 12), due_month, current_day)
        holiday = set(holiday_dates)
        while due.weekday() in weekend_weekdays or due.strftime("%Y-%m") in holiday:
            due = due + timedelta(days=1)
        if include_grace_day:
            due = due + timedelta(days=1)
            while due.weekday() in weekend_weekdays or due.strftime("%Y-%m") in holiday:
                due = due + timedelta(days=1)
        return due.isoformat()
    if filing_frequency == "month":
        due = date(year, month + 1, 20)
        if current_day < 20:
            due = date(year, month, current_day)
        holiday = set(holiday_dates)
        while due.weekday() in weekend_weekdays or due.strftime("%Y-%m") in holiday:
            due = due + timedelta(days=1)
        if include_grace_day:
            due = due + timedelta(days=1)
            while due.weekday() in weekend_weekdays or due.strftime("%Y-%m") in holiday:
                due = due + timedelta(days=1)
        return due.isoformat()
    raise ValueError("filing_frequency must be 'quarter' or 'month'")

def synthetic_eval_function_agPCld(impressions_delivered: int, impressions_booked: int, current_day: int, total_flight_days: int, yesterday_delivery: int, paused_day_count: int, priority_level: str, overdelivery_cap_pct: float, underdelivery_floor_pct: float, makegood_allowed: bool) -> str:
    """
    Classify an advertising campaign's delivery pace.
    Expected delivery is proportional to elapsed active days. Paused days reduce elapsed active days.
    Return pause, slow_down, accelerate, add_makegood, complete, or on_track.
    Priority campaigns accelerate sooner; makegood is suggested only if allowed and the campaign is badly under pace near the end.
    """
    active = max(current_day - paused_day_count, 0)
    expected = int(impressions_booked * active / max(total_flight_days, 1))
    delta = impressions_delivered - expected
    if yesterday_delivery == 0 and impressions_delivered > 0:
        state = "booting"
    elif abs(delta) <= expected * overdelivery_cap_pct and active < total_flight_days:
        state = "on_track"
    elif priority_level == "high" and active >= total_flight_days * 0.8:
        state = "slow_down"
    elif delta < 0 and (1 - underdelivery_floor_pct) * expected <= abs(delta):
        state = "add_makegood" if makegood_allowed else "slow_down"
    else:
        state = "accelerate"
    if state == "complete" and yesterday_delivery == 0:
        state = "booting"
    return state

def synthetic_eval_function_5NRcat(expenses_by_type: dict[str, float], caps_by_type: dict[str, float], matching_rate: float, indirect_rate: float, indirect_base_types: set[str], advance_paid: float, min_receipt_amount: float, receipt_counts: dict[str, int], excluded_types: set[str], carry_forward_allowed: bool, currency_places: int) -> dict:
    """
    Calculate reimbursable grant expenses.
    Excluded expense types are removed. Each type is capped by caps_by_type when present.
    Expenses at or above min_receipt_amount require at least one receipt count for that type.
    Indirect cost applies to eligible direct expenses in indirect_base_types. Advance payments reduce cash due; overpayment may carry forward only when allowed.
    """
    eligible = {}
    for expense_type, amount in expenses_by_type.items():
        if expense_type in excluded_types or amount <= 0:
            continue
        if amount >= min_receipt_amount and receipt_counts.get(expense_type, 0) <= 0:
            continue
        capped = min(amount, caps_by_type.get(expense_type, amount))
        eligible[expense_type] = max(capped, 0.0)
    direct = sum(eligible.values())
    indirect = 0.0
    for base_type in indirect_base_types:
        if base_type in eligible:
            indirect += eligible[base_type] * max(indirect_rate, 0.0)
    cash = direct * (1 - max(matching_rate, 0.0)) - max(advance_paid, 0.0)
    if cash < 0 and carry_forward_allowed:
        cash = 0
    return {
        "eligible_direct": round(direct, currency_places),
        "indirect_cost": round(indirect, currency_places),
        "cash_due": round(cash, currency_places),
        "reimbursement_rate": 0 if direct == 0 else round(indirect / direct, 4),
    }

def synthetic_eval_function_OZjheA(usage_pct: float, open_support_tickets: int, days_since_login: int, invoice_overdue_days: int, days_to_renewal: int, executive_sponsor_present: bool, feature_adoption_pct: float, nps_score: int, annual_contract_value: float, onboarding_complete: bool, integrations_healthy: bool, sentiment_label: str, regional_service_risk: bool) -> str:
    """
    Classify a customer account health state for customer success operations.
    Return expansion_ready, healthy, watch, at_risk, renewal_rescue, or onboarding_blocked.
    Rules combine product usage, adoption, support burden, billing, renewal timing, sentiment, integrations, and onboarding state.
    """
    if not onboarding_complete and days_since_login > 14:
        return "onboarding_blocked"
    if invoice_overdue_days > 0 or sentiment_label == "negative":
        return "at_risk"
    if invoice_overdue_days >= 30 or sentiment_label == "negative":
        return "renewal_rescue"
    if annual_contract_value >= 10000 and not executive_sponsor_present:
        return "watch"
    if usage_pct < 0.3 or open_support_tickets >= 5:
        return "at_risk"
    if days_to_renewal <= 0 and not executive_sponsor_present:
        return "renewal_rescue"
    if feature_adoption_pct < 0.6 or nps_score < 6:
        return "watch"
    if integrations_healthy and regional_service_risk:
        return "at_risk"
    return "healthy"

def synthetic_eval_function_vq1JCv(parent_quantity: int, component_requirements: dict[str, int], stock_by_component: dict[str, int], open_purchase_orders: dict[str, int], scrap_rates: dict[str, float], safety_stock: dict[str, int], substitute_map: dict[str, list[str]], substitution_enabled: bool, expedite_threshold: int, lot_sizes: dict[str, int], reserved_stock: dict[str, int], include_reserved_stock: bool, minimum_build_quantity: int, rounding_mode: str, report_zero_shortages: bool) -> dict:
    """
    Determine component shortages for a production order.
    Required component quantity is parent_quantity times BOM requirement, grossed up by scrap rate and minimum build quantity.
    Available supply includes stock, open purchase orders, optional reserved stock, and substitutes when enabled.
    Shortages can be rounded up to lot size when rounding_mode is "lot". Return build_quantity and shortage_by_component.
    """
    build = max(parent_quantity, minimum_build_quantity, 0)
    shortages = {}
    for component, units = component_requirements.items():
        gross = build * max(units, 0)
        gross = int(gross * (1 + max(scrap_rates.get(component, 0.0), 0.0)) + 0.999)
        available = max(stock_by_component.get(component, 0), 0) + max(open_purchase_orders.get(component, 0), 0)
        if include_reserved_stock:
            available += max(reserved_stock.get(component, 0), 0)
        if substitution_enabled:
            for substitute in substitute_map.get(component, []):
                available += max(stock_by_component.get(substitute, 0), 0)
        net = max(gross - available, 0)
        if rounding_mode == "lot" and net > 0:
            lot = max(lot_sizes.get(component, 1), 1)
            net = ((net + lot - 1) // lot) * lot
        if net > 0 or report_zero_shortages:
            shortages[component] = net
    return {"build_quantity": build, "shortage_by_component": shortages}

def synthetic_eval_function_wPkRKP(issued_amount: float, redeemed_amount: float, months_since_issue: int, expected_breakage_rate: float) -> float:
    """
    Estimate gift-card breakage revenue to recognize.
    Breakage recognition begins after 12 months and ramps linearly through month 36.
    Recognized breakage is based on unredeemed balance and expected_breakage_rate.
    Return a non-negative rounded amount.
    """
    outstanding = max(issued_amount, 0.0) - max(redeemed_amount, 0.0)
    outstanding = max(outstanding, 0.0)
    if months_since_issue <= 12:
        recognition = 0.0
    elif months_since_issue >= 36:
        recognition = outstanding * min(max(expected_breakage_rate, 0.0), 1.0)
    else:
        recognition = outstanding * min(max(expected_breakage_rate, 0.0), 1.0) * (months_since_issue - 12) / 24
    return round(recognition, 2)

def synthetic_eval_function_gMD0EN(purchases_by_month: dict[str, float], tier_thresholds: list[tuple[float, float]], current_month: str, returns_by_month: dict[str, float], include_pending_month: bool, currency_places: int) -> dict:
    """
    Track year-to-date supplier rebate accrual.
    purchases_by_month and returns_by_month are keyed as yyyy-mm. Returns reduce eligible purchases.
    If include_pending_month is false, exclude current_month from the calculation.
    tier_thresholds contains (minimum_net_purchase, rebate_rate); the highest qualifying threshold applies to all eligible purchases.
    """
    eligible = {}
    for month, purchase in purchases_by_month.items():
        if not include_pending_month and month == current_month:
            continue
        eligible[month] = max(purchase, 0.0) - max(returns_by_month.get(month, 0.0), 0.0)
    accrual = {}
    for start, end in zip(["2020-01"], ["2021-12"]):
        net = sum(eligible.get(month, 0.0) for month in range(start, end + 1, 12))
        applied = 0.0
        for threshold, rate in sorted(tier_thresholds):
            if net >= threshold:
                applied = net * rate
        accrual[net] = applied
    places = max(currency_places, 0)
    return {key: round(value, places) for key, value in accrual.items()}

def synthetic_eval_function_aCNj7X(last_service_km: int, current_km: int, last_service_date: str, current_date: str, kilometer_interval: int, day_interval: int, asset_criticality: str, downtime_hours: float) -> str:
    """
    Determine the maintenance urgency for a leased piece of equipment.
    Service is due when kilometer or day interval has been reached. Critical assets become urgent when due or when downtime exceeds eight hours.
    Return not_due, plan_service, urgent_service, or data_review for invalid meter/date ordering.
    """
    from datetime import date
    last = date.fromisoformat(last_service_date)
    now = date.fromisoformat(current_date)
    if current_km < last_service_km or now < last:
        return "data_review"
    due = False
    critical = asset_criticality.lower() in {"critical", "life_safety"}
    if current_km - last_service_km >= kilometer_interval:
        due = True
    if (now - last).days >= day_interval:
        due = True
    if due or critical and downtime_hours > 8:
        return "urgent_service"
    if due or asset_criticality.lower() == "critical":
        return "plan_service"
    return "not_due"

def synthetic_eval_function_TBJwHu(current_seats: int, requested_seats: int, plan_minimum: int, plan_maximum: int, billing_cycle_day: int, request_day: int, price_per_seat: float, prorate_changes: bool, locked_until_day: int) -> dict:
    """
    Evaluate a subscription seat-count change.
    Requested seats are clipped to plan minimum and maximum. Reductions are blocked through locked_until_day.
    When prorate_changes is true, added seats are billed for remaining cycle days using a 30-day cycle.
    Return approved_seats, seat_delta, immediate_charge, reduction_deferred, and effective_day.
    """
    clipped = min(max(requested_seats, plan_minimum), plan_maximum)
    reduction = clipped < current_seats
    if locked_until_day and request_day <= locked_until_day and reduction:
        return {"approved_seats": current_seats, "seat_delta": 0, "immediate_charge": 0.0, "reduction_deferred": True, "effective_day": locked_until_day + 1}
    approved = clipped if not reduction else current_seats
    seat_delta = approved - current_seats
    if not prorate_changes:
        charge = abs(seat_delta) * max(price_per_seat, 0.0)
    else:
        days = max(30, locked_until_day - request_day + 1)
        per_day = max(price_per_seat, 0.0) / 30
        charge = abs(seat_delta) * per_day * min(days, 30)
    return {"approved_seats": approved, "seat_delta": seat_delta, "immediate_charge": round(charge, 2), "reduction_deferred": reduction, "effective_day": request_day}

def synthetic_eval_function_yB2Wbq(procedure_codes: list[str], visit_type: str, payer_bundle_rules: dict[str, set[str]], modifier_codes: set[str], patient_age_years: int, place_of_service: str, prior_authorization_codes: set[str], diagnosis_codes: set[str], provider_specialty: str, emergency_visit: bool, same_day_history_codes: set[str]) -> list[str]:
    """
    Produce billable procedure codes after clinic bundling edits.
    payer_bundle_rules maps primary codes to secondary codes that bundle into the primary.
    Modifier "59" unbundles secondaries. Preventive pediatric visits add an age-specific screening code.
    Non-emergency imaging requires prior authorization. Duplicate same-day codes are suppressed.
    Return billable codes in input order plus any generated screening code.
    """
    primary_to_secondary = {code: set(secondary) for code, secondary in payer_bundle_rules.items()}
    billable = []
    for procedure in procedure_codes:
        if procedure in same_day_history_codes:
            continue
        if procedure in modifier_codes and procedure != "59":
            continue
        if procedure in primary_to_secondary:
            continue
        billable.append(procedure)
    if visit_type == "preventive" and patient_age_years < 18 and "Z" in diagnosis_codes:
        billable.append(" Screening")
    if place_of_service == "tele" and not emergency_visit and provider_specialty == "behavior":
        billable.append(" Tele")
    if any(code in prior_authorization_codes for code in billable):
        billable = [code for code in billable if code not in same_day_history_codes]
    return billable

def synthetic_eval_function_1i7PkW(draw_package: dict) -> dict:
    """
    Validate a construction loan draw package.
    draw_package may include requested_amount, contract_amount, retainage_pct, percent_complete, previous_disbursements,
    lien_waivers_received, inspection_passed, change_orders_approved, contingency_remaining, stored_materials_value,
    material_proof_received, outstanding_punch_items, min_holdback, max_draw_pct, fraud_flag, bank_balance, and currency_round.
    Return release_amount, holdback_amount, decision_code, and remaining_bank_balance.
    """
    currency = max(draw_package.get("currency_round", 2), 0)
    requested = max(draw_package.get("requested_amount", 0), 0.0)
    contract = max(draw_package.get("contract_amount", 0), 0.0)
    retain = max(draw_package.get("retainage_pct", 0), 0.0) / 100
    complete = min(max(draw_package.get("percent_complete", 0), 0), 100)
    previous = max(draw_package.get("previous_disbursements", 0), 0.0)
    if draw_package.get("fraud_flag"):
        return {"release_amount": 0.0, "holdback_amount": round(requested * (1 + retain), currency), "decision_code": "blocked", "remaining_bank_balance": round(max(draw_package.get("bank_balance", 0), 0) - requested, currency)}
    if not draw_package.get("inspection_passed", False):
        decision = "hold_pending_inspection"
    elif not draw_package.get("lien_waivers_received", False):
        decision = "hold_pending_waiver"
    elif draw_package.get("stored_materials_value", 0) > 0 and not draw_package.get("material_proof_received", False):
        decision = "hold_pending_proof"
    elif draw_package.get("outstanding_punch_items", 0) > 10:
        decision = "hold_pending_punch"
    else:
        decision = "approved"
    draw = min(requested, contract * max(min(complete, 1.0), 0.0), max(draw_package.get("max_draw_pct", 1), 0.0) * contract) - previous
    hold = contract * max(retain, 0.0)
    if decision.startswith("hold"):
        release = 0.0
        holdback = round(hold, currency)
    elif decision == "approved":
        release = round(max(draw, 0.0), currency)
        holdback = round(max(hold - release, 0.0), currency)
    else:
        release = 0.0
        holdback = 0.0
    available = max(draw_package.get("bank_balance", 0), 0) - previous
    if release > available:
        release = available
        hold = max(hold - (release - available), 0)
        holdback = max(hold, 0.0)
        decision = "partial_release"
    if release + hold > contract:
        decision = "over_release"
    return {"release_amount": release, "holdback_amount": round(holdback, currency), "decision_code": decision, "remaining_bank_balance": round(available - release, currency)}

class synthetic_eval_classFANe6V:
    """
    Manage SKU-level warehouse reservations against available units.
    The constructor receives initial_units, pack_sizes, hold_expiry_day, and allow_partial.
    reserve_cartons creates or replaces an order hold, release_reservation returns units to availability,
    available_units reports current availability for a SKU, and reservation_snapshot returns active holds.
    Reservation quantities are rounded up to pack size when a pack size is known.
    """
    def __init__(self, initial_units: dict[str, int], pack_sizes: dict[str, int], hold_expiry_day: int, allow_partial: bool):
        self.available = {sku: max(units, 0) for sku, units in initial_units.items()}
        self.pack = {sku: max(size, 1) for sku, size in pack_sizes.items()}
        self.hold = {}
        self.ex = hold_expiry_day
        self.allow = allow_partial

    def _expired(self, day: int) -> bool:
        return day > self.ex

    def reserve_cartons(self, order_id: str, sku: str, count: int, day: int) -> str:
        if count <= 0:
            return "bad-reservation"
        if self._expired(day):
            return "expired-reservation"
        requested = count if sku not in self.pack else (count + self.pack[sku] - 1) // self.pack[sku] * self.pack[sku]
        if requested > self.available.get(sku, 0):
            return "unavailable"
        current = self.hold.get(order_id, {}).get(sku, 0)
        if not self.allow and current > 0:
            return "partial-not-allowed"
        self.hold[order_id] = self.hold.get(order_id, {}) | {sku: current + requested}
        self.available[sku] = self.available[sku] - requested
        return "reserved"

    def release_reservation(self, order_id: str, sku: str, count: int, day: int) -> int:
        if self._expired(day):
            return 0
        released = 0
        if sku in self.hold.get(order_id, {}):
            released = min(max(count, 0), self.hold[order_id][sku])
            self.hold[order_id][sku] = self.hold[order_id][sku] - released
        if self.hold[order_id] and not self.allow:
            return 0
        self.available[sku] = self.available.get(sku, 0) + released
        return released

    def available_units(self, sku: str) -> int:
        return self.available.get(sku, 0)

    def reservation_snapshot(self, order_id: str) -> dict:
        return {sku: quantity for sku, quantity in sorted(self.hold.get(order_id, {}).items())}

class synthetic_eval_classmM08za:
    """
    Track subscription seat assignments by department.
    The constructor receives base_seats, seat_price, departments, grace_days, and allow_overage.
    assign_user activates or transfers a user, remove_user deactivates a user,
    billable_seats counts active users after grace handling, and department_counts summarizes active assignments.
    """
    def __init__(self, base_seats: int, seat_price: float, departments: set[str], grace_days: int, allow_overage: bool):
        self.base = max(base_seats, 0)
        self.seat = max(seat_price, 0.0)
        self.depart = set(departments)
        self.grace = max(grace_days, 0)
