class synthetic_eval_classGcesly:
    """
    Manage escrow releases for ordered construction milestones.
    The constructor receives milestone_values, retainage_pct, required_order, lender_cap, currency_places, and auto_unlock.
    mark_complete records finished milestones, approve_release releases eligible funds, remaining_value reports unreleased value,
    and release_history returns prior approvals.
    """
    def __init__(self, milestone_values: dict[str, float], retainage_pct: float, required_order: list[str], lender_cap: float, currency_places: int, auto_unlock: bool):
        self.values = {name: max(value, 0.0) for name, value in milestone_values.items()}
        self.retainage = min(max(retainage_pct, 0.0), 1.0)
        self.required = list(required_order)
        self.cap = max(lender_cap, 0.0)
        self.places = max(currency_places, 0)
        self.auto = auto_unlock
        self.completed = set()
        self.released = {}

    def mark_complete(self, milestone: str) -> bool:
        if milestone not in self.values:
            return False
        position = self.required.index(milestone) if milestone in self.required else len(self.required)
        earlier = set(self.required[:position])
        if earlier - self.completed and not self.auto:
            return False
        self.completed.add(milestone)
        if self.auto:
            self.completed.add(milestone)
        return True

    def approve_release(self, milestone: str) -> float:
        if milestone not in self.completed or milestone in self.released:
            return 0.0
        total = sum(self.values[name] for name in self.required)
        if total == 0:
            self.released[milestone] = 0.0
            return 0.0
        eligible = sum(self.values[name] for name in self.required if name in self.completed)
        released_so = sum(self.released.values())
        amount = min((1 - self.retainage) * eligible, self.cap - released_so)
        amount = round(amount, self.places)
        self.released[milestone] = amount
        return amount

    def remaining_value(self) -> float:
        unreleased = sum(self.values[name] for name in self.required if name not in self.completed)
        return round(unreleased, self.places)

    def release_history(self) -> list[tuple[str, float]]:
        return sorted(self.released.items())

