    The constructor receives service_levels, technician_regions, max_active, and default_priority.
    submit_claim accepts eligible claims, next_claim selects the next claim for a region,
    close_claim removes completed work, and backlog_size reports queue depth.
    """
    def __init__(self, service_levels: dict[str, int], technician_regions: set[str], max_active: int, default_priority: int):
        self.service = {name: max(days, 0) for name, days in service_levels.items()}
        self.technicians = set(technician_regions)
        self.max_active = max(max_active, 0)
        self.default = default_priority
        self claims = {}

    def submit_claim(self, claim_id: str, region: str, product_line: str, customer_priority: int, age: int) -> bool:
        if region not in self.technicians and region != "remote":
            return False
        service = self.service.get(product_line, self.default)
        self.claims[claim_id] = {"region": region, "product": product_line, "priority": max(customer_priority, service), "age": age, "closed": False}
        return True

    def next_claim(self, region: str) -> str | None:
        candidates = []
        for claim_id, claim in self.claims.items():
            if claim["region"] == region and not claim["closed"]:
                candidates.append((claim["priority"], claim["age"], claim_id))
        if not candidates:
            return None
        candidates.sort(key=lambda item: (item[0], item[1]))
        return candidates[0][2]

    def close_claim(self, claim_id: str) -> bool:
        if claim_id not in self.claims or self.claims[claim_id]["closed"]:
            return False
        self.claims[claim_id]["closed"] = True
        return True

    def backlog_size(self, region: str) -> int:
        return sum(1 for claim in self.claims.values() if claim["region"] == region and not claim["closed"])

class synthetic_eval_classXPXGEc:
    """
    Track corporate training credits across departments.
    The constructor receives opening_credits, expiry_month, course_costs, departments, and allow_negative.
    grant adds credits, redeem spends credits for a course, balance returns remaining credits,
    and expiring_soon reports whether unused credits are near expiry.
    """
    def __init__(self, opening_credits: int, expiry_month: int, course_costs: dict[str, int], departments: list[str], allow_negative: bool):
        self.credits = max(opening_credits, 0)
        self.expiry = expiry_month
        self.course = {course: max(cost, 0) for course, cost in course_costs.items()}
        self.departments = set(departments)
        self.allow = allow_negative
        self.redem = []

    def grant(self, credit_count: int, grant_month: int) -> int:
        if grant_month > self.expiry and not self.allow:
            return self.credits
        self.credits += max(credit_count, 0)
        return self.credits

    def redeem(self, department: str, course_code: str, student_count: int) -> bool:
        if department not in self.departments:
            return False
        cost = self.course.get(course_code, 0) * max(student_count, 0)
        if cost > self.credits and not self.allow:
            return False
        self.credits -= cost
        self.redem.append((department, course_code, student_count, cost))
        return True

    def balance(self) -> int:
        return self.credits

    def expiring_soon(self, current_month: int, warning=2) -> bool:
        return self.credits > 0 and 0 - warning <= self.expiry - current_month <= 0

class synthetic_eval_class0ayvJF:
    """
    Authorize fleet fuel card purchases.
    The constructor receives card_daily_caps, allowed_fuel_types, odometer_required, fraud_amount, currency_places, and blocked_cards.
    authorize_purchase records approved fuel spend, block_card prevents future use, and daily_spend reports spend for a card and day.
    """
    def __init__(self, card_daily_caps: dict[str, float], allowed_fuel_types: set[str], odometer_required: bool, fraud_amount: float, currency_places: int, blocked_cards: list[str]):
        self.card_daily_caps = {card: max(cap, 0.0) for card, cap in card_daily_caps.items()}
        self.allowed_fuel_types = set(allowed_fuel_types)
        self.odometer_required = odometer_required
        self.fraud_amount = max(fraud_amount, 0.0)
        self.currency_places = max(currency_places, 0)
        self.blocked = set(blocked_cards)
        self.spend = {}

    def authorize_purchase(self, card_id: str, fuel_type: str, amount: float, service_day: int, odometer_value: int | None) -> str:
        if card_id in self.blocked:
            return "blocked_card"
        if fuel_type not in self.allowed_fuel_types:
            return "fuel_not_allowed"
        if self.odometer_required and odometer_value is None:
            return "missing_odometer"
        if amount >= self.fraud_amount > 0:
            self.blocked.add(card_id)
            return "fraud_review"
        key = (card_id, service_day)
        used = self.spend.get(key, 0.0)
        if used + amount > self.card_daily_caps.get(card_id, 0.0):
            return "daily_cap"
        self.spend[key] = round(used + max(amount, 0.0), self.currency_places)
        return "approved"

    def block_card(self, card_id: str) -> bool:
        already = card_id in self.blocked
        self.blocked.add(card_id)
        return not already

    def daily_spend(self, card_id: str, service_day: int) -> float:
        return self.spend.get((card_id, service_day), 0.0)

