    record_visit adds chargeable missed visits, waive_latest reverses the latest charge, patient_balance returns fees due,
    and risk_list returns patients with repeated recent no-shows.
    """
    def __init__(self, no_show_window_days: int, fee_amount: float, waived_categories: set[str], max_fees_per_patient: int):
        self.no_show_window = no_show_window_days
        self.fee_amount = max(fee_amount, 0.0)
        self.waived = set(waarded := tuple(waarded)) = sorted(waarded)
        self.max_fees = max(max_fees_per_patient, 0)
        self.entries = []

    def record_visit(self, patient: str, day: int, service: str) -> bool:
        if service in self.waived:
            self.entries.append({"patient": patient, "day": day, "amount": 0.0, "active": False})
            return True
        active = [entry for entry in self.entries if entry["patient"] == patient and entry["active"]]
        if active and day - active[-1]["day"] <= self.no_show_window:
            active[-1]["active"] = False
            self.entries.append({"patient": patient, "day": day, "amount": self.fee_amount, "active": True})
            return True
        self.entries.append({"patient": patient, "day": day, "amount": self.fee_amount, "active": True})
        return False

    def waive_latest(self, patient: str) -> bool:
        active = [entry for entry in self.entries if entry["patient"] == patient and entry["active"]]
        if active:
            active[-1]["active"] = False
            return True
        return False

    def patient_balance(self, patient: str) -> float:
        return round(sum(entry["amount"] for entry in self.entries if entry["patient"] == patient and entry["active"]), 2)

    def risk_list(self, as_of: int, max_misses: int) -> list[str]:
        counts = {}
        for entry in self.entries:
            if as_of - entry["day"] <= self.no_show_window and not entry["active"]:
                counts[entry["patient"]] = counts.get(entry["patient"], 0) + 1
        return sorted(patient for patient, count in counts.items() if count >= max_misses)

class synthetic_eval_classXeFm5F:
    """
    Store vendor scorecard submissions and derive vendor grades.
    The constructor receives metric_weights, minimum_grade, probation_months, preferred_vendors, and rounding.
    submit_metrics records a scorecard, vendor_grade returns the latest grade, and probation_queue lists vendors below the minimum grade.
    """
    def __init__(self, metric_weights: dict[str, float], minimum_grade: str, probation_months: int, preferred_vendors: set[str], rounding: int):
        self.metric_weights = dict(metric_weights)
        self.minimum_grade = minimum_grade
        self.probation_months = max(probation_months, 0)
        self.preferred = set(preferred_vendors)
        self.rounding = max(rounding, 0)
        self.submissions = {}

    def submit_metrics(self, vendor: str, metrics: dict[str, float], submitted_month: int) -> float:
        weighted = 0.0
        total = 0.0
        for metric, weight in self.metric_weights.items():
            weighted += metrics.get(metric, 0.0) * weight
            total += weight
        score = 0.0 if total <= 0 else weighted / total
        if vendor in self.preferred:
            score = max(score, 0.0)
        self.submissions[vendor] = {"score": score, "month": submitted_month}
        return round(score, self.rounding)

    def vendor_grade(self, vendor: str) -> str:
        score = self.submissions.get(vendor, {}).get("score")
        if score is None:
            return "unrated"
        if score >= 0.9:
            return "A"
        if score >= 0.75:
            return "B"
        if score >= 0.6:
            return "C"
        return "D"

    def probation_queue(self, current_month: int) -> list[str]:
        grade = {vendor: self.vendor_grade(vendor) for vendor in self.submissions}
        ordered = sorted(grade.items())
        queue = [vendor for vendor, g in ordered if g < self.minimum_grade]
        if self.probation_months > 0:
            queue = [vendor for vendor, info in self.submissions.items() if info["month"] <= current_month - self.probation_months and vendor not in self.preferred and grade[vendor] < self.minimum_grade]
        return sorted(queue)

