    """
    Stage and quote catering orders for internal events.
    The constructor receives menu_prices, dietary_multipliers, service_fee_pct, minimum_headcount, reusable_packaging, and currency_places.
    stage_order creates an order, revise_headcount changes attendees, quote prices it, and clear_order removes it.
    """
    def __init__(self, menu_prices: dict[str, float], dietary_multipliers: dict[str, float], service_fee_pct: float, minimum_headcount: int, reusable_packaging: bool, currency_places: int):
        self.menu = {name: max(price, 0.0) for name, price in menu_prices.items()}
        self.diet = {name: max(multi, 0.0) for name, multi in dietary_multipliers.items()}
        self.service = max(service_fee_pct, 0.0)
        self.min_head = max(minimum_headcount, 0)
        self.reusable = reusable_packaging
        self.places = max(currency_places, 0)
        self.orders = {}

    def stage_order(self, order_id: str, menu_code: str, headcount: int, dietary = {}) -> bool:
        if menu_code not in self.menu:
            return False
        self.orders[order_id] = {"menu": menu_code, "headcount": max(headcount, 0), "diet": dict(dietary)}
        return True

    def revise_headcount(self, order_id: str, new_headcount: int) -> bool:
        if order_id not in self.orders:
            return False
        self.orders[order_id]["headcount"] = max(new_headcount, 0)
        return True

    def quote(self, order_id: str) -> dict:
        order = self.orders.get(order_id)
        if order is None:
            return {"subtotal": 0.0, "service": 0.0, "total": 0.0, "included_packaging": 0.0}
        head = max(order["headcount"], self.min_head)
        diet = order["diet"]
        subtotal = head * self.menu[order["menu"]]
        for name, multi in diet.items():
            subtotal *= 1 + max(multi, 0.0)
        if self.reusable:
            subtotal -= 10
        service = subtotal * self.service
        total = subtotal + service
        return {"subtotal": round(subtotal, self.places), "service": round(service, self.places), "total": round(total, self.places), "included_packaging": round(0 if self.reusable else 10, self.places)}

    def clear_order(self, order_id: str) -> bool:
        return self.orders.pop(order_id, None) is not None

