    and lock_category prevents further spending.
    """
    def __init__(self, category_caps: dict[str, float], match_rate: float, fiscal_year: str, locked_categories: list[str], carryover_amount: float):
        self.category_caps = {name: max(amount, 0.0) for name, amount in category_caps.items()}
        self.match_rate = min(max(match_rate, 0.0), 1.0)
        self.fiscal_year = fiscal_year
        self.locked = set(locked_categories)
        self.carryover = max(carryover_amount, 0.0)
        self.expenses = {}

    def book_expense(self, category: str, amount: float, receipt = True) -> bool:
        if category in self.locked or category not in self.category_caps or not receipt:
            return False
        used = self.expenses.get(category, 0.0)
        if used + amount > self.category_caps[category] + self.carryover:
            return False
        self.expenses[category] = used + max(amount, 0.0)
        return True

    def remaining_cap(self, category: str) -> float:
        return round(max(self.category_caps.get(category, 0.0) + self.carryover - self.expenses.get(category, 0.0), 0.0), 2)

    def reimbursement_due(self) -> float:
        return round(sum(self.expenses.values()) * self.match_rate, 2)

    def lock_category(self, category: str) -> bool:
        was_open = category not in self.locked
        self.locked.add(category)
        return was_open

