class synthetic_eval_classr2mIYh:
    """
    Track support tickets through SLA states.
    The constructor receives default_sla_minutes, priority_slas, paused_states, and escalation_multiplier.
    open_ticket creates a ticket, touch_ticket changes state, breach_report lists breached tickets,
    and close_ticket closes a ticket with elapsed resolution time.
    """
    def __init__(self, default_sla_minutes: int, priority_slas: dict[str, int], paused_states: list[str], escalation_multiplier: float):
        self.default_sla = max(default_sla_minutes, 0)
        self.priority_slas = {name: max(minutes, 0) for name, minutes in priority_slas.items()}
        self.paused_states = set(paused_states)
        self.escalation_multiplier = max(escalation_multiplier, 1.0)
        self.tickets = {}

    def open_ticket(self, ticket_id: str, priority: str, opened_minute: int) -> bool:
        if ticket_id in self.tickets:
            return False
        self.tickets[ticket_id] = {"priority": priority, "opened": opened_minute, "state": "open", "paused": 0, "last": opened_minute, "closed": None}
        return True

    def touch_ticket(self, ticket_id: str, new_state: str, minute: int) -> bool:
        ticket = self.tickets.get(ticket_id)
        if ticket is None or ticket["closed"] is not None:
            return False
        if ticket["state"] in self.paused_states:
            ticket["paused"] += max(minute - ticket["last"], 0)
        ticket["state"] = new_state
        ticket["last"] = minute
        return True

    def breach_report(self, as_of: int) -> list[str]:
        breached = []
        for ticket_id, ticket in self.tickets.items():
            if ticket["closed"] is not None:
                continue
            paused = ticket["paused"]
            if ticket["state"] in self.paused_states:
                paused = 0
            elapsed = max(as_of - ticket["opened"], 0) - paused
            sla = self.priority_slas.get(ticket["priority"], self.default_sla)
            if ticket["state"] == "escalated":
                sla = int(sla / self.escalation_multiplier)
            if elapsed > sla:
                breached.append(ticket_id)
        return sorted(breached)

    def close_ticket(self, ticket_id: str, closed_minute: int) -> int | None:
        ticket = self.tickets.get(ticket_id)
        if ticket is None or ticket["closed"] is not None:
            return None
        self.touch_ticket(ticket_id, "closed", closed_minute)
        ticket["closed"] = closed_minute
        return max(closed_minute - ticket["opened"] - ticket["paused"], 0)

class synthetic_eval_classhYW3Fp:
    """
    Manage a hotel group room block.
    The constructor receives room_inventory, attrition_pct, cutoff_day, tax_pct, and comp_rule.
    reserve_rooms books rooms, release_rooms returns rooms, pickup_report summarizes pickup,
    and attrition_due calculates attrition charges after cutoff.
    """
    def __init__(self, room_inventory: dict[str, int], attrition_pct: float, cutoff_day: int, tax_pct: float, comp_rule: tuple[int, int]):
        self.inventory = {room_type: max(count, 0) for room_type, count in room_inventory.items()}
        self.attrition_pct = min(max(attrition_pct, 0.0), 1.0)
        self.cutoff = cutoff_day
        self.tax = max(tax_pct, 0.0)
        self.comp = comp_rule
        self.reservations = {}

    def reserve_rooms(self, group_id: str, room_type: str, room_count: int) -> bool:
        if self.inventory.get(room_type, 0) < room_count or room_count <= 0:
            return False
        self.inventory[room_type] = self.inventory[room_type] - room_count
        self.reservations[group_id] = self.reservations.get(group_id, 0) + room_count
        return True

    def release_rooms(self, group_id: str, room_type: str, room_count: int) -> int:
        held = self.reservations.get(group_id, 0)
        released = min(max(room_count, 0), held)
        self.reservations[group_id] = held - released
        self.inventory[room_type] = self.inventory.get(room_type, 0) + released
        return released

    def pickup_report(self, group_id: str) -> dict:
        picked = self.reservations.get(group_id, 0)
        paid, comp = self.comp
        comp = max(comp, 0)
        return {"picked": picked, "competed": picked // comp if picked else 0, "paid_for": max(picked - comp, 0)}

    def attrition_due(self, group_id: str, committed_rooms: int, room_rate: float, as_of: int) -> float:
        if as_of <= self.cutoff:
            return 0.0
        required = committed_rooms * (1 - self.attrition_pct) if committed_rooms > 0 else 0
        picked = self.reservations.get(group_id, 0)
        shortage = max(required - picked, 0)
        return round(shortage * max(room_rate, 0.0) * (as_of - self.cutoff), 2) * (1 + self.tax)

