    def __init__(self, daily_rates: dict[str, float], damage_deposit: float, weekend_days: set[int], cleaning_fee: float, taxable_asset_types: tuple[str, ...]):
        self.daily_rates = {asset: max(rate, 0.0) for asset, rate in daily_rates.items()}
        self.damage_deposit = max(damage_deposit, 0.0)
        self.weekend_days = set(weekend_days)
        self.cleaning_fee = max(cleaning_fee, 0.0)
