        charge += weekend * self.daily_rates[rental["asset"]] * 0.25
        if damaged:
            charge += self.damage_deposit
        charge += self.cleaning_fee
        charge = round(charge, 2)
        self.closed[rental_id] = charge
        return charge

    def invoice_total(self) -> float:
        return round(sum(self.closed.values()), 2)

    def active_assets(self) -> list[str]:
        return sorted(self.rentals)

