    """
    Manage store-level retail price overrides.
    The constructor receives base_prices, approver_roles, protected_skus, max_discount_pct, and expiry_day.
    propose_override records a pending override, approve_override activates it, current_price reads the effective price,
    and expire_overrides removes stale active overrides.
    """
    def __init__(self, base_prices: dict[str, float], approver_roles: list[str], protected_skus: set[str], max_discount_pct: float, expiry_day: int):
        self.base = {sku: max(price, 0.0) for sku, price in base_prices.items()}
        self.approver = set(approver_roles)
        self.prot = set(protected_skus)
        self.max = min(max(max_discount_pct, 0.0), 1.0)
        self.ex = expiry_day
        self.pending = {}
        self.active = {}

    def propose_override(self, sku: str, proposed_price: float, request_day: int) -> bool:
        if sku not in self.base or sku in self.prot:
            return False
        discount = 1 - proposed_price / self.base[sku] if self.base[sku] else 0
        if discount > self.max:
            return False
        self.pending[sku] = {"price": max(proposed_price, 0.0), "day": request_day}
        return True

    def approve_override(self, sku: str, approver: str) -> bool:
        if approver not in self.approver or sku not in self.pending:
            return False
        self.active[sku] = self.pending.pop(sku)
        return True

    def current_price(self, sku: str) -> float:
        if sku in self.active:
            return self.active[sku]["price"]
        return self.base.get(sku, 0.0)

    def expire_overrides(self, current_day: int) -> int:
        stale = [sku for sku, override in self.active.items() if current_day - override["day"] > self.ex]
        for sku in stale:
            del self.active[sku]
        return len(stale)

class synthetic_eval_classaiUba0:
    """
    Track campaign pledges and payments.
    The constructor receives campaign_goal, matching_rules, allowed_funds, pledge_window, and currency_places.
    record_pledge creates a pledge, receive_payment applies cash, outstanding_by_donor reports balances,
    and campaign_progress reports received and matched progress toward the goal.
    """
    def __init__(self, campaign_goal: float, matching_rules: dict[str, float], allowed_funds: set[str], pledge_window: tuple[int, int], currency_places: int):
        self.campaign_goal = max(campaign_goal, 0.0)
        self.matching_rules = {fund: max(rate, 0.0) for fund, rate in matching_rules.items()}
        self.allowed_funds = set(allowed_funds)
        self.pledge_window = pledge_window
        self.currency_places = max(currency_places, 0)
        self.pledges = {}

    def record_pledge(self, pledge_id: str, donor_id: str, fund: str, amount: float, pledge_day: int) -> bool:
        start_day, end_day = self.pledge_window
        if fund not in self.allowed_funds or not (start_day <= pledge_day <= end_day) or amount <= 0:
            return False
        self.pledges[pledge_id] = {"donor": donor_id, "fund": fund, "amount": amount, "paid": 0.0}
        return True

    def receive_payment(self, pledge_id: str, amount: float) -> float:
        pledge = self.pledges.get(pledge_id)
        if pledge is None:
            return 0.0
        applied = min(max(amount, 0.0), pledge["amount"] - pledge["paid"])
        pledge["paid"] += applied
        return round(applied, self.currency_places)

    def outstanding_by_donor(self, donor_id: str) -> float:
        due = sum(pledge["amount"] - pledge["paid"] for pledge in self.pledges.values() if pledge["donor"] == donor_id)
        return round(max(due, 0.0), self.currency_places)

    def campaign_progress(self) -> dict:
        received = sum(pledge["paid"] for pledge in self.pledges.values())
        matched = sum(pledge["paid"] * self.matching_rules.get(pledge["fund"], 0.0) for pledge in self.pledges.values())
        total = received + matched
        percent = 0.0 if self.campaign_goal == 0 else total / self.campaign_goal
        return {"received": round(received, self.currency_places), "matched": round(matched, self.currency_places), "progress_percent": round(percent, 4)}

