    add_endorsement activates an endorsement, cancel_endorsement removes it, premium_due computes earned premium,
    and active_endorsements lists current endorsements.
    """
    def __init__(self, base_premium: float, endorsement_rates: dict[str, float], effective_day: int, cancellation_day: int | None, minimum_earned_pct: float):
        self.base = max(base_premium, 0.0)
        self.rates = dict(endorsement_rates)
        self.effective = effective_day
        self.cancellation = cancellation_day
        self.minimum = min(max(minimum_earned_pct, 0.0), 1.0)
        self.active = {}

    def add_endorsement(self, endorsement_code: str, start_day: int) -> bool:
        if endorsement_code not in self.rates:
            return False
        if self.cancellation is not None and start_day >= self.cancellation:
            self.active[endorsement_code] = start_day
            return True
        return False

    def cancel_endorsement(self, endorsement_code: str) -> bool:
        return self.active.pop(endorsement_code, None) is not None

    def premium_due(self, as_of: int) -> float:
        end = min(as_of, self.cancellation) if self.cancellation is not None else as_of
        premium = self.base
        for code, start in self.active.items():
            if start <= end:
                premium *= 1 + self.rates[code]
        return max(premium * self.minimum, 0.0)

    def active_endorsements(self) -> list[str]:
        return sorted(self.active)

class synthetic_eval_classYpHkqN:
    """
    Manage maintenance parts stock and job reservations.
    The constructor receives initial_bins, reorder_points, vendor_priority, emergency_markup, allow_substitutes, and reserved_jobs.
    issue_part consumes stock, restock_part adds stock, reorder_list identifies replenishment needs, and reserve_for_job holds parts for a job.
    """
    def __init__(self, initial_bins: dict[str, int], reorder_points: dict[str, int], vendor_priority: list[str], emergency_markup: float, allow_substitutes: bool, reserved_jobs: set[str]):
        self.bins = {part: max(count, 0) for part, count in initial_bins.items()}
        self.reorder = {part: max(count, 0) for part, count in reorder_points.items()}
        self.vendor_priority = list(vendor_priority)
        self.emergency_markup = max(emergency_markup, 0.0)
        self.allow_sub = allow_substitutes
        self.reservations = {job: {} for job in reserved_jobs}

    def issue_part(self, part_id: str, quantity: int) -> int:
        issued = min(max(quantity, 0), self.bins.get(part_id, 0))
        self.bins[part_id] = self.bins.get(part_id, 0) - issued
        return issued

    def restock_part(self, part_id: str, quantity: int, vendor: str) -> float:
        self.bins[part_id] = self.bins.get(part_id, 0) + max(quantity, 0)
        priority = 0 if vendor not in self.vendor_priority else self.vendor_priority.index(vendor)
        return round(max(quantity * (1 + self.emergency_markup), 0.0), 2)

    def reorder_list(self) -> list[str]:
        return sorted(part for part in self.reorder if self.bins.get(part, 0) <= self.reorder[part])

    def reserve_for_job(self, job_id: str, part_id: str, quantity: int) -> bool:
        if job_id not in self.reservations:
            self.reservations[job_id] = {}
        issued = self.issue_part(part_id, quantity)
        if issued < quantity and not self.allow_sub:
            self.bins[part_id] = self.bins.get(part_id, 0) + issued
            return False
        self.reservations[job_id][part_id] = self.reservations[job_id].get(part_id, 0) + issued
        return issued > 0

class synthetic_eval_class16F1Ed:
    """
    Manage carrier tenders by shipping lane.
    The constructor receives carrier_rates, service_scores, lane_blackouts, fuel_pct, and currency_places.
    add_quote records a lane quote, award_lane selects the best eligible carrier, tender_history returns awards,
    and clear_lane removes open quotes for a lane.
    """
    def __init__(self, carrier_rates: dict[str, float], service_scores: dict[str, float], lane_blackouts: set[str], fuel_pct: float, currency_places: int):
        self.carrier_rates = {carrier: max(rate, 0.0) for carrier, rate in carrier_rates.items()}
        self.service = {carrier: max(score, 0.0) for carrier, score in service_scores.items()}
        self.lane_blackouts = set(lane_blackouts)
        self.fuel = max(fuel_pct, 0.0)
        self.currency = max(currency_places, 0)
        self.quotes = {}
        self.awards = []

    def add_quote(self, lane: str, carrier: str, freight = 0.0, detention = 0.0, weekend = False) -> bool:
        if lane in self.lane_blackouts:
            return False
        if carrier not in self.carrier_rates:
            return False
        detention = max(detention, 0.0)
        fee = detention * 0.05 if weekend else 0.0
        self.quotes.setdefault(lane, {})[carrier] = {"rate": self.carrier_rates[carrier], "freight": max(freight, 0.0), "fee": fee, "service": self.service[carrier], "active": True}
        return True

    def award_lane(self, lane: str) -> str:
        lane_quotes = self.quotes.get(lane, {})
        if not lane_quotes:
            return ""
        best = max(lane_quotes.items(), key=lambda item: (item[1]["rate"] * (1 + self.fuel) - item[1]["service"], item[1]["service"], item[1]["freight"], -len(item[0])))[0]
        self.awards.append((lane, best, round(lane_quotes[best]["rate"] * (1 + self.fuel) - lane_quotes[best]["service"], self.currency)))
        for quote in lane_quotes.values():
            quote["active"] = False
        return best

    def tender_history(self) -> list[tuple[str, str, float]]:
        return list(self.awards)

    def clear_lane(self, lane: str) -> int:
        original = self.quotes.get(lane, {})
        self.quotes[lane] = {carrier: quote for carrier, quote in original.items() if quote["active"]}
        return len(self.quotes[lane])

class synthetic_eval_classQV7VRX:
    """
    Route incoming clinic referrals to specialty queues.
    The constructor receives specialty_capacity, urgent_keywords, payer_specialty_rules, default_specialty, and max_age_days.
    submit_referral queues a referral, route_next selects work for a specialty, age_referrals removes stale entries,
    and queue_lengths reports queue depths.
    """
    def __init__(self, specialty_capacity: dict[str, int], urgent_keywords: set[str], payer_specialty_rules: dict[str, str], default_specialty: str, max_age_days: int):
        self.specialty_capacity = {name: max(cap, 0) for name, cap in specialty_capacity.items()}
        self.urgent_keywords = {word.lower() for word in urgent_keywords}
        self.payer_specialty = dict(payer_specialty_rules)
        self.default = default_specialty
        self.max_age = max(max_age_days, 0)
        self.queues = {name: [] for name in specialty_capacity}

    def submit_referral(self, referral_id: str, payer: str, keywords: list[str], received_day: int) -> str:
        specialty = self.payer_specialty.get(payer, self.default)
        if specialty not in self.queues:
            self.queues[specialty] = []
        urgent = any(word in self.urgent_keywords for word in keywords)
        self.queues[specialty].append({"id": referral_id, "day": received_day, "urgent": urgent})
        self.queues[specialty].sort(key=lambda row: (not row["urgent"], row["day"], row["id"]))
        return specialty

    def route_next(self, specialty: str) -> str | None:
        queue = self.queues.get(specialty, [])
        if not queue or self.specialty_capacity.get(specialty, 0) <= 0:
            return None
        self.specialty_capacity[specialty] -= 1
        return queue.pop(0)["id"]

    def age_referrals(self, current_day: int) -> int:
        removed = 0
        for specialty, queue in self.queues.items():
            fresh = [row for row in queue if current_day - row["day"] <= self.max_age]
            removed += len(queue) - len(fresh)
            self.queues[specialty] = fresh
        return removed

    def queue_lengths(self) -> dict:
        return {specialty: len(queue) for specialty, queue in sorted(self.queues.items())}

