    and resolve_notice closes a notice.
    """
    def __init__(self, response_days_by_notice: dict[str, int], weekend_days: set[int], holiday_days: set[int], escalation_days: int, jurisdiction_codes: tuple[str, ...]):
        self.response_days = {notice: max(days, 0) for notice, days in response_days_by_notice.items()}
        self.weekend = set(weekend_days)
        self.holiday = set(holiday_days)
        self.escalation = max(escalation_days, 0)
        self.juris = set(jurisdiction_codes)
        self.notices = {}

    def add_notice(self, notice_id: str, notice_type: str, received_day: int, jurisdiction: str) -> bool:
        if jurisdiction not in self.juris:
            return False
        self.notices[notice_id] = {"type": notice_type, "received": received_day, "resolved": False}
        return True

    def due_date(self, notice_id: str) -> int:
        notice = self.notices.get(notice_id)
        if notice is None:
            return None
        due = notice["received"] + self.response_days.get(notice["type"], 30)
        while due % 7 in self.weekend or due in self.holiday:
            due += 1
        return due

    def escalate_due(self, current_day: int) -> list[str]:
        due = {}
        for notice_id, notice in self.notices.items():
            if notice["resolved"]:
                continue
            due_date = self.due_date(notice_id)
            if due_date is None:
                continue
            if current_day >= due_date - self.escalation:
                due[notice_id] = due_date
        return sorted(due)

    def resolve_notice(self, notice_id: str) -> bool:
        if notice_id not in self.notices or self.notices[notice_id]["resolved"]:
            return False
        self.notices[notice_id]["resolved"] = True
        return True

