    """
    def __init__(self, benefit_caps: dict[str, float], rollover_allowed: bool, member_tiers: list[str], reset_month: int, excluded_benefits: set[str]):
        self.benefit_caps = {name: max(cap, 0.0) for name, cap in benefit_caps.items()}
        self.rollover_allowed = rollover_allowed
        self.member_tiers = set(member_tiers)
        self.reset_month = reset_month
        self.excluded = set(excluded_benefits)
        self.wallets = {}

    def grant_year(self, member_id: str, tier: str) -> bool:
        if tier not in self.member_tiers:
            return False
        self.wallets[member_id] = {name: cap for name, cap in self.benefit_caps.items() if name not in self.excluded}
        return True

    def use_benefit(self, member_id: str, benefit: str, amount: float) -> float:
        wallet = self.wallets.get(member_id)
        if wallet is None or benefit not in wallet:
            return 0.0
        used = min(max(amount, 0.0), wallet[benefit])
        wallet[benefit] -= used
        return round(used, 2)

    def remaining_benefit(self, member_id: str, benefit: str) -> float:
        return round(self.wallets.get(member_id, {}).get(benefit, 0.0), 2)

    def reset_member_year(self, member_id: str, current_month: int) -> bool:
        if current_month != self.reset_month or member_id not in self.wallets:
            return False
        old = self.wallets[member_id]
        self.wallets[member_id] = {}
        for name, cap in self.benefit_caps.items():
            if name in self.excluded:
                continue
            rol = cap if self.rollover_allowed and old.get(name, 0.0) > 0 else 0.0
            self.wallets[member_id][name] = rol
        return True

