    submit_change creates a change order, approve_next advances approvals, committed_total reports approved exposure,
    and pending_dependencies lists required approvals still missing.
    """
    def __init__(self, allowance_by_trade: dict[str, float], approval_order: list[str], contingency_balance: float, auto_number_prefix: str, tax_pct: float):
        self.allowance = {trade: max(amount, 0.0) for trade, amount in allowance_by_trade.items()}
        self.approval = list(approval_order)
        self.contingency = max(contingency_balance, 0.0)
        self.auto = auto_number_prefix
        self.tax = max(tax_pct, 0.0)
        self._changes = {}

    def submit_change(self, change_id: str, trade: str, amount: float) -> bool:
        if change_id in self._changes:
            return False
        self._changes[change_id] = {"trade": trade, "amount": max(amount, 0.0), "approved": set()}
        return True

    def approve_next(self, change_id: str, role: str) -> bool:
        change = self._changes.get(change_id)
        if change is None or role not in self.approval:
            return False
        if role in change["approved"]:
            return True
        index = self.approval.index(role)
        if index == len(change["approved"]):
            change["approved"].add(role)
            return True
        return False

    def committed_total(self) -> float:
        total = 0.0
        for change in self._changes.values():
            if len(change["approved"]) == len(self.approval):
                trade = change["trade"]
                total += change["amount"] * self.allowance.get(trade, 1.0)
        return round(total + self.contingency, 2)

    def pending_dependencies(self, change_id: str) -> list[str]:
        change = self._changes.get(change_id)
        if change is None:
            return []
        return [role for role in self.approval if role not in change["approved"]]

class synthetic_eval_classoTouyT:
    """
    Manage customer invoice disputes.
    The constructor receives reason_slas, auto_credit_reasons, materiality_amount, escalation_roles, and currency_places.
    open_dispute records a dispute, classify_dispute returns its handling class, apply_resolution closes it,
    and aging_bucket summarizes open dispute ages.
    """
    def __init__(self, reason_slas: dict[str, int], auto_credit_reasons: set[str], materiality_amount: float, escalation_roles: list[str], currency_places: int):
        self.reason_slas = {reason: max(days, 0) for reason, days in reason_slas.items()}
        self.auto_credit_reasons = set(auto_credit_reasons)
        self.materiality_amount = max(materiality_amount, 0.0)
        self.escalation_roles = list(escalation_roles)
        self.currency_places = max(currency_places, 0)
        self.disputes = {}

    def open_dispute(self, dispute_id: str, reason: str, amount: float, opened_day: int) -> bool:
        if dispute_id in self.disputes:
            return False
        self.disputes[dispute_id] = {"reason": reason, "amount": max(amount, 0.0), "opened": opened_day, "closed": False, "credit": 0.0}
        return True

    def classify_dispute(self, dispute_id: str, current_day: int) -> str:
        dispute = self.disputes.get(dispute_id)
        if dispute is None:
            return "missing"
        if dispute["closed"]:
            return "closed"
        if dispute["reason"] in self.auto_credit_reasons and dispute["amount"] <= self.materiality_amount:
            return "auto_credit"
        if current_day - dispute["opened"] > self.reason_slas.get(dispute["reason"], 14):
            return "escalate"
        return "analyst_review"

    def apply_resolution(self, dispute_id: str, approved_credit: float) -> float:
        dispute = self.disputes.get(dispute_id)
        if dispute is None or dispute["closed"]:
            return 0.0
        credit = min(max(approved_credit, 0.0), dispute["amount"])
        dispute["credit"] = credit
        dispute["closed"] = True
        return round(credit, self.currency_places)

    def aging_bucket(self, current_day: int) -> dict:
        buckets = {"0-7": 0, "8-30": 0, "31+": 0}
        for dispute in self.disputes.values():
            if dispute["closed"]:
                continue
            age = current_day - dispute["opened"]
            if age <= 7:
                buckets["0-7"] += 1
            elif age <= 30:
                buckets["8-30"] += 1
            else:
                buckets["31+"] += 1
        return buckets

class synthetic_eval_classiHkr6z:
    """
    Track data-subject privacy requests.
    The constructor receives response_sla_days, identity_required_types, allowed_request_types, hold_reasons, and extension_days.
    submit_request creates a request, verify_identity marks it verified, advance_request changes lifecycle state,
    and overdue_requests lists open overdue requests.
    """
    def __init__(self, response_sla_days: int, identity_required_types: set[str], allowed_request_types: tuple[str, ...], hold_reasons: set[str], extension_days: int):
        self.response_sla = max(response_sla_days, 0)
        self.identity_required = set(identity_required_types)
        self.allowed = set(allowed_request_types)
        self.hold = dict()
        self.extension = max(extension_days, 0)
        self.requests = {}

    def submit_request(self, request_id: str, request_type: str, received_day: int) -> bool:
        if request_type not in self.allowed:
            return False
        verified = request_type not in self.identity_required
        self.requests[request_id] = {"type": request_type, "received": received_day, "verified": verified, "state": "intake", "hold": None}
        return True

    def verify_identity(self, request_id: str) -> bool:
        request = self.requests.get(request_id)
        if request is None:
            return False
        request["verified"] = True
        return True

    def advance_request(self, request_id: str, new_state: str, hold_reason: str | None = None) -> bool:
        request = self.requests.get(request_id)
        if request is None or (new_state != "intake" and not request["verified"]):
            return False
        request["state"] = new_state
        request["hold"] = hold_reason
        return True

    def overdue_requests(self, current_day: int) -> list[str]:
        overdue = []
        for request_id, request in self.requests.items():
            if request["state"] == "closed":
                continue
            due = request["received"] + self.response_sla
            if request["hold"] in self.hold and self.hold[request] <= current_day:
                due = min(due, self.hold[request] + self.extension)
            if current_day > due:
                overdue.append(request_id)
        return sorted(overdue)

