    submit_purchase opens a request, approve records role approvals, current_step reports the next required role,
    and approved_amount returns approved spend.
    """
    def __init__(self, threshold_by_role: dict[str, float], approver_order: list[str], restricted_categories: set[str], emergency_override_role: str, currency_places: int):
        self.threshold = {role: max(amount, 0.0) for role, amount in threshold_by_role.items()}
        self.approver = list(approver_order)
        self.restricted = set(restricted_categories)
        self.emergency = emergency_override_role
        self.places = max(currency_places, 0)
        self.requests = {}

    def submit_purchase(self, request_id: str, amount: float, category: str, emergency: bool) -> bool:
        if request_id in self.requests:
            return False
        self.requests[request_id] = {"amount": max(amount, 0.0), "category": category, "emergency": emergency, "approvals": []}
        return True

    def approve(self, request_id: str, role: str) -> bool:
        request = self.requests.get(request_id)
        if request is None:
            return False
        if request["emergency"] and role == self.emergency:
            request["approvals"] = list(self.approver)
            return True
        required = self.current_step(request_id)
        if role != required:
            return False
        request["approvals"].append(role)
        return True

    def current_step(self, request_id: str) -> str | None:
        request = self.requests.get(request_id)
        if request is None:
            return None
        needed = []
        for role in self.approver:
            if request["amount"] > self.threshold.get(role, 0.0) or self.restricted and request["category"] in self.restricted:
                needed.append(role)
        for role in needed:
            if role not in request["approvals"]:
                return role
        return None

    def approved_amount(self) -> float:
        total = sum(request["amount"] for request in self.requests.values() if self.current_step(next(rid for rid, row in self.requests.items() if row is request)) is None)
        return round(total, self.places)

