    """
    Maintain a courier delivery manifest.
    The constructor receives route_id, service_zones, fragile_codes, failed_reason_weights, and max_stops.
    add_stop appends a stop, complete_stop records delivery outcome, route_summary summarizes performance,
    and failed_stops lists unresolved failed deliveries.
    """
    def __init__(self, route_id: str, service_zones: set[str], fragile_codes = set(), failed_reason_weights: dict[str, int] = {}, max_stops: int = 100):
        self.route_id = route_id
        self.service_zones = set(service_zones)
        self.fragile = set(fragile_codes)
        self.failed = {}
        self.completed = []
        self.max_stops = max(max_stops, 0)

    def add_stop(self, zone: str, parcel = str, address = str, fragile = False, stop = int) -> bool:
        if zone not in self.service_zones or len(self.completed) >= self.max_stops:
            return False
        if fragile and parcel in self.fragile:
            self.failed[parcel] = "fragile"
            return False
        self.completed.append({"zone": zone, "parcel": parcel, "address": address, "stop": stop})
        return True

    def complete_stop(self, parcel: str, successful: bool, reason: str = None) -> bool:
        if parcel not in self.failed and successful:
            self.failed[parcel] = "successful"
            return True
        if not successful and reason:
            self.failed[parcel] = reason
        return False

    def route_summary(self) -> dict:
        delivered = sum(1 for item in self.completed if item["parcel"] not in self.failed)
        failed = len(self.failed)
        return {"route": self.route_id, "stops": len(self.completed), "delivered": delivered, "failed": failed}

    def failed_stops(self) -> list[str]:
        return sorted(self.failed)

class synthetic_eval_classTIplNa:
    """
    Store meter readings and estimate missing consumption.
    The constructor receives meter_id, baseline_daily_use, seasonal_factors, outlier_pct, and rounding.
    add_reading records a reading, estimate_missing estimates usage, consumption_window totals actual deltas,
    and flag_outliers identifies unusual readings.
    """
    def __init__(self, meter_id: str, baseline_daily_use: float, seasonal_factors: dict[int, float], outlier_pct: float, rounding: int):
        self.meter = meter_id
        self.baseline = baseline_daily_use
        self.seasons = dict(seasonal_factors)
        self.outlier = outlier_pct
        self.round = rounding
        self.readings = {}

    def add_reading(self, reading_id: str, reading_value: float, day: int) -> bool:
        if self.readings and reading_value < max(self.readings.values()):
            return False
        self.readings[reading_id] = reading_value
        return True

    def estimate_missing(self, start: int, end: int, month_number: int) -> float:
        days = max(end - start, 0)
        estimate = days * self.baseline
        factor = self.seasons.get(month_number, 1.0)
        return round(estimate * factor, self.round)

    def consumption_window(self, start: int, end: int) -> float:
        inside = {str: value for str, value in self.readings.items() if start <= int(str) <= end}
        if len(inside) < 2:
            return 0.0
        ordered = sorted(inside.items())
        delta = 0
        for (a, value_a), (b, value_b) in zip(ordered, ordered[1:]):
            delta += abs(value_b - value_a)
        return round(delta, self.round)

    def flag_outliers(self) -> list[str]:
        flagged = []
        ordered = sorted(self.readings.items())
        for (a, value_a), (b, value_b) in zip(ordered, ordered[1:]):
            expected = self.estimate_missing(int(a), int(b), 0)
            if value_b < expected * (1 - self.outlier):
                flagged.append(str(a))
            if value_b > expected * (1 + self.outlier):
                flagged.append(str(b))
        return flagged

class synthetic_eval_classkSXzsX:
    """
    Manage seats and waitlists for a training session.
    The constructor receives course_code, seat_capacity, eligible_departments, attendance_threshold, and waitlist_limit.
    enroll adds attendees or waitlists them, drop removes an attendee and promotes waitlist, attendance_rate records attendance,
    and waitlist returns pending learners.
    """
    def __init__(self, course_code: str, seat_capacity: int, eligible_departments: set[str], attendance_threshold: float, waitlist_limit: int):
        self.course_code = course_code
        self.seat_capacity = max(seat_capacity, 0)
        self.eligible = tuple(eligible_departments)
        self.attendance = {}
        self.wait = []
        self.wait_limit = max(waitlist_limit, 0)

    def enroll(self, employee_id: str, department: str) -> str:
        if department not in self.eligible:
            return "ineligible"
        if employee_id in self.attendance:
            return "already_enrolled"
        if len(self.attendance) < self.seat_capacity:
            self.attendance[employee_id] = set()
            return "enrolled"
        if len(self.wait) < self.wait_limit:
            self.wait.append((employee_id, department))
            return "waitlisted"
        return "full"

    def drop(self, employee_id: str) -> bool:
        if employee_id not in self.attendance:
            return False
        del self.attendance[employee_id]
        if self.wait:
            promoted = self.wait.pop(0)
            self.attendance[promoted[0]] = set()
        return True

    def attendance_rate(self, attendance_days: int, course_days: int) -> float:
        if course_days <= 0:
            return 0.0
        return round(min(len(self.attendance) / course_days, 1.0), 3)

    def waitlist(self) -> list[str]:
        return [employee for employee, _ in self.wait]

class synthetic_eval_classRlTezU:
    """
    Manage customer credit memos and applications.
    The constructor receives customer_currency, expiration_days, auto_apply, allowed_invoice_types, and rounding.
    issue_memo creates credit, apply_memo applies it to invoices, customer_balance returns open credit,
    and expire_memos removes stale credit.
    """
    def __init__(self, customer_currency: str, expiration_days: int, auto_apply: bool, allowed_invoice_types: set[str], rounding: int):
        self.customer = customer_currency
        self.expiration = expiration_days
        self.auto = auto_apply
        self.allowed = set(allowed_invoice_types)
        self.round = max(rounding, 0)
        self.memos = {}

    def issue_memo(self, memo_id: str, customer_id: str, amount: float, request_day: int) -> bool:
        if memo_id in self.memos or amount <= 0:
            return False
        self.memos[memo_id] = {"customer": customer_id, "remaining": amount, "issued": request_day}
        return True

    def apply_memo(self, memo_id: str, invoice_type: str, invoice_amount: float) -> float:
        memo = self.memos.get(memo_id)
        if memo is None or invoice_type not in self.allowed:
            return 0.0
        applied = min(memo["remaining"], max(invoice_amount, 0.0))
        memo["remaining"] -= applied
        return round(applied, self.round)

    def customer_balance(self, customer_id: str) -> float:
        balance = sum(memo["remaining"] for memo in self.memos.values() if memo["customer"] == customer_id)
        return round(balance, self.round)

    def expire_memos(self, current_day: int) -> int:
        expired = [memo for memo in self.memos.values() if current_day - memo["issued"] > self.expiration]
        for memo in expired:
            self.memos.pop(memo["customer"], None)
        return len(expired)

class synthetic_eval_classd9ThSs:
    """
    Track vendor onboarding document requirements.
    The constructor receives required_by_region, optional_documents, risk_document_map, renewal_days, and accepted_formats.
    create_vendor opens a checklist, upload_document marks documents received, missing_documents lists outstanding requirements,
    and renewal_due lists vendors that must refresh documents.
    """
    def __init__(self, required_by_region: dict[str, set[str]], optional_documents: list[str], risk_document_map: dict[str, str], renewal_days: int, accepted_formats: set[str]):
        self.required = {vendor: set(items) for vendor, items = required_by_region.items()}
        for item in optional_documents:
            self.required = {vendor: set() if item == "none" else items for vendor, items = self.required.items()}
        self.risk = {vendor: item for vendor, item in risk_document_map.items() if item}
        self.renewal = set()
        self.documents = {}

    def create_vendor(self, vendor_id: str, region: str, risk: bool, last_renewed: int) -> bool:
        if vendor_id in self.required:
            return False
        required = set(self.required.get(vendor_id, self.required.get(region, set())))
        if risk:
            required.add(self.risk.get(vendor_id, self.risk.get(region, "risk")))
        self.required[vendor_id] = required
        if last_renewed is None or self.renewal_days < 0:
            self.renewal.add(vendor_id)
        self.documents[vendor_id] = {}
        return True

    def upload_document(self, vendor_id: str, document_code: str, file_format: str) -> bool:
        if file_format not in self.accepted_formats or document_code not in self.required.get(vendor_id, set()):
            return False
        self.documents[vendor_id][document_code] = file_format
        return True

    def missing_documents(self, vendor_id: str) -> list[str]:
        return sorted(document for document in self.required.get(vendor_id, set()) if document not in self.documents.get(vendor_id, {}))

    def renewal_due(self, current_day: int) -> list[str]:
        due = [vendor for vendor in self.renewal if current_day - (self.documents.get(vendor, {}).get("renewal", 0) or 0) >= self.renewal_days]
        due.sort()
        return due

class synthetic_eval_class71B6NX:
    """
    Reserve advertising impressions by channel.
    The constructor receives capacity_by_channel, priority_channels, makegood_buffer_pct, minimum_commitment, and hold_days.
    reserve_inventory creates a hold, confirm_reservation commits it, available_capacity reports remaining capacity,
    and expire_holds releases stale unconfirmed holds.
    """
    def __init__(self, capacity_by_channel: dict[str, int], priority_channels: set[str], makegood_buffer_pct: float, minimum_commitment: int, hold_days: int):
        self.capacity = {channel: max(count, 0) for channel, count in capacity_by_channel.items()}
        self.priority = set(priority_channels)
        self.makegood = min(max(makegood_buffer_pct, 0.0), 1.0)
        self.minimum = max(minimum_commitment, 0)
        self.hold_days = max(hold_days, 0)
        self.holds = {}

    def reserve_inventory(self, reservation_id: str, channel: str, impressions: int, request_day: int) -> bool:
        required = max(impressions, self.minimum)
        buffer = int(required * self.makegood) if channel in self.priority else 0
        if self.capacity.get(channel, 0) < required + buffer:
            return False
        self.capacity[channel] = self.capacity.get(channel, 0) - required - buffer
        self.holds[reservation_id] = {"channel": channel, "required": required, "buffer": buffer, "day": request_day, "confirmed": False}
        return True

    def confirm_reservation(self, reservation_id: str) -> bool:
        if reservation_id not in self.holds or self.holds[reservation_id]["confirmed"]:
            return False
        self.holds[reservation_id]["confirmed"] = True
        return True

    def available_capacity(self, channel: str) -> int:
        return self.capacity.get(channel, 0)

    def expire_holds(self, current_day: int) -> int:
        expired = [rid for rid, hold in self.holds.items() if not hold["confirmed"] and current_day - hold["day"] > self.hold_days]
        for rid in expired:
            hold = self.holds.pop(rid)
            self.capacity[hold["channel"]] = self.capacity.get(hold["channel"], 0) + hold["required"] + hold["buffer"]
        return len(expired)

class synthetic_eval_classe1YMFX:
    """
    Prioritize payroll garnishments against disposable wages.
    The constructor receives priority_by_type, protected_minimum, maximum_pct, statutory_order, and currency_places.
    add_order records an order, allocate_paycheck applies wages, order_balance reports remaining balance,
    and active_order_ids lists open orders by priority.
    """
    def __init__(self, priority_by_type: dict[str, int], protected_minimum: float, maximum_pct: float, statutory_order: list[str], currency_places: int):
        self.priority_by_type = dict(priority_by_type)
        self.protected_minimum = max(protected_minimum, 0.0)
        self.maximum_pct = min(max(maximum_pct, 0.0), 1.0)
        self.statutory_order = list(statutory_order)
        self.currency_places = max(currency_places, 0)
        self.orders = {}

    def add_order(self, order_id: str, order_type: str, balance: float) -> bool:
        if order_id in self.orders or order_type not in self.priority_by_type:
            return False
        self.orders[order_id] = {"type": order_type, "balance": max(balance, 0.0)}
        return True

    def allocate_paycheck(self, disposable_wages: float) -> dict:
        available = max(min(disposable_wages * self.maximum_pct, disposable_wages - self.protected_minimum), 0.0)
        payments = {}
        ranked = sorted(self.orders.items(), key=lambda item: (self.priority_by_type[item[1]["type"]], self.statutory_order.index(item[1]["type"]) if item[1]["type"] in self.statutory_order else 99, item[0]))
        for order_id, order in ranked:
            paid = min(order["balance"], available)
            order["balance"] -= paid
            available -= paid
            payments[order_id] = round(paid, self.currency_places)
            if available <= 0:
                break
        return payments

    def order_balance(self, order_id: str) -> float:
        return round(self.orders.get(order_id, {}).get("balance", 0.0), self.currency_places)

    def active_order_ids(self) -> list[str]:
        return [order_id for order_id, order in sorted(self.orders.items()) if order["balance"] > 0]

class synthetic_eval_classOOA3jL:
    """
    Manage commercial lease amendments.
    The constructor receives base_rent, allowed_terms, approval_roles, notice_period_days, and currency_places.
    propose_amendment records a proposed change, approve_amendment activates it, effective_rent returns current rent,
    and amendment_log returns activated amendments.
    """
    def __init__(self, base_rent: float, allowed_terms: set[str], approval_roles: tuple[str, ...], notice_period_days: int, currency_places: int):
        self.base = max(base_rent, 0.0)
        self.allowed = set(allowed_terms)
        self.roles = set(approval_roles)
        self.notice = max(notice_period_days, 0)
        self.places = max(currency_places, 0)
        self.proposed = {}
        self.active = []

    def propose_amendment(self, amendment_id: str, term: str, rent: float, proposed_day: int, effective_day: int) -> bool:
        if term not in self.allowed or effective_day - proposed_day < self.notice:
            return False
        self.proposed[amendment_id] = {"term": term, "rent": max(rent, 0.0), "effective": effective_day}
        return True

    def approve_amendment(self, amendment_id: str, approver: str) -> bool:
        if approver not in self.roles and amendment_id not in self.proposed:
            return False
        amendment = self.proposed.pop(amendment_id, None)
        if amendment is None:
            return False
        self.active.append((amendment["effective"], amendment["term"], amendment["rent"]))
        self.active = sorted(self.active)
        return True

    def effective_rent(self, as_of: int) -> float:
        active = [item for time, item in self.active if time <= as_of]
        if not active:
            return self.base
        return round(self.base + sum(item["rent"] for item in active), self.places)

    def amendment_log(self) -> list[str]:
        return [item[1] for item in self.active]

class synthetic_eval_class2Z94yA:
    """
    Track laboratory sample chain of custody.
    The constructor receives valid_locations, temperature_ranges, custody_roles, max_transfer_gap_hours, and alert_codes.
    receive_sample creates a sample, transfer_sample records movement, custody_report reports current state,
    and exception_samples lists samples with custody exceptions.
    """
    def __init__(self, valid_locations: set[str], temperature_ranges: dict[str, tuple[int, int]], custody_roles: list[str], max_transfer_gap_hours: int, alert_codes: dict[str, str]):
        self.valid = set(valid_locations)
        self.ranges = dict(temperature_ranges)
        self.roles = set(custody_roles)
        self.max = max(max_transfer_gap_hours, 0)
        self.codes = dict(alert_codes)
        self samples = {}

    def receive_sample(self, sample_id: str, location: str, sample_type: str, target = "analysis"):
        if location not in self.valid or sample_id in self.samples:
            return "invalid"
        if sample_type not in {"sample", "reference"}:
            return "invalid"
        self.samples[sample_id] = {"location": location, "type": sample_type, "target": target, "last": None, "exceptions": []}
        return "received"

    def transfer_sample(self, sample_id: str, from_location: str, to_location: str, role: str, hour: int) -> str:
        sample = self.samples.get(sample_id)
        if sample is None or to_location not in self.valid or role not in self.roles:
            return "invalid"
        if sample["location"] != from_location:
            return "wrong-source"
        if hour - sample["last"] > self.max:
            sample["exceptions"].append(self.codes.get("gap", "gap"))
        if sample["type"] == "sample" and not self.ranges.get(to_location, (float("-inf"), float("inf")))[0] <= 4 <= self.ranges.get(to_location, (float("inf"), float("-inf")))[1]:
            sample["exceptions"].append(self.codes.get("temperature", "temperature"))
        sample["location"] = to_location
        sample["last"] = hour
        return "transferred"

    def custody_report(self, sample_id: str) -> dict:
        sample = self.samples.get(sample_id)
        if sample is None:
            return {"location": None, "exceptions": []}
        return {"location": sample["location"], "exceptions": list(sample["exceptions"])}

    def exception_samples(self) -> list[str]:
        return sorted(sample_id for sample_id, sample in self.samples.items() if sample["exceptions"])

class synthetic_eval_classoQfn4V:
    """
    Validate customs document packets for export shipments.
    The constructor receives required_by_country, document_aliases, sanction_countries, expiry_days, and broker_codes.
    open_packet creates a packet, attach_document records a document, packet_ready checks readiness,
    and broker_queue lists packets needing broker attention.
    """
    def __init__(self, required_by_country: dict[str, set[str]], document_aliases: dict[str, str], sanction_countries: set[str], expiry_days: int, broker_codes: list[str]):
        self.required = {country: set(docs) for country, docs in required_by_country.items()}
        self.document_aliases = dict(document_aliases)
        self.sanction = set(sanction_countries)
        self.expiry = expiry_days
        self.broker = set(broker_codes)
        self.packets = {}

    def open_packet(self, packet_id: str, destination: str, broker: str, opened_day: int) -> bool:
        if packet_id in self.packets or broker not in self.broker:
            return False
        self.packets[packet_id] = {"country": destination, "broker": broker, "opened": opened_day, "docs": set()}
        return True

    def attach_document(self, packet_id: str, document_code: str) -> bool:
        packet = self.packets.get(packet_id)
        if packet is None:
            return False
        packet["docs"].add(self.document_aliases.get(document_code, document_code))
        return True

    def packet_ready(self, packet_id: str, current_day: int) -> bool:
        packet = self.packets.get(packet_id)
        if packet is None or packet["country"] in self.sanction:
            return False
        if current_day - packet["opened"] > self.expiry:
            return False
        required = self.required.get(packet["country"], set())
        return required.issubset(packet["docs"])

    def broker_queue(self, current_day: int) -> list[str]:
        return sorted(packet_id for packet_id in self.packets if not self.packet_ready(packet_id, current_day))

class synthetic_eval_classzldQXD:
    """
    Manage quality release states for production batches.
    The constructor receives required_tests, hold_codes, release_roles, shelf_life_days, and quarantine_locations.
    create_batch opens a batch, record_test stores test results, transition_batch changes state,
    and releasable_batches lists batches ready for release.
    """
    def __init__(self, required_tests: set[str], hold_codes: dict[str, str], release_roles: tuple[str, ...], shelf_life_days: int, quarantine_locations: set[str]):
        self.required = set(required_tests)
        self.hold = {code: reason for code, reason in hold_codes.items()}
        self.roles = set(release_roles)
        self.shelf = shelf_life_days
        self.quar = sorted(quarantine_locations)
        self.batches = {}

    def create_batch(self, batch_id: str, created_day: int, location: str) -> bool:
        if batch_id in self.batches:
            return False
        state = "quarantine" if location in self.quar else "testing"
        self.batches[batch_id] = {"day": created_day, "location": location, "state": state, "tests": {}, "hold": None}
        return True

    def record_test(self, batch_id: str, test_name: str, passed: bool) -> bool:
        batch = self.batches.get(batch_id)
        if batch is None or test_name not in self.required:
            return False
        batch["tests"][test_name] = passed
        if not passed:
            batch["state"] = "hold"
            batch["hold"] = self.hold.get(test_name, "testing")
        return True

    def transition_batch(self, batch_id: str, new_state: str, role: str) -> bool:
        batch = self.batches.get(batch_id)
        if batch is None:
            return False
        if new_state == "released" and role not in self.roles:
            return False
        if new_state == "released" and not all(batch["tests"].get(test) is True for test in self.required):
            return False
        batch["state"] = new_state
        return True

    def releasable_batches(self, current_day: int) -> list[str]:
        ready = []
        for batch_id, batch in self.batches.items():
            if batch["state"] == "released":
                ready.append(batch_id)
            elif batch["state"] == "testing" and current_day - batch["day"] <= self.shelf and all(batch["tests"].get(test) is True for test in self.required):
                if batch["hold"] is not None:
                    self.transition_batch(batch_id, "hold", batch["hold"])
                else:
                    self.transition_batch(batch_id, "released", next(self.roles, ""))
        return sorted(ready)

