        if not self.site.get(site_id, set()).issubset(self.crew.get(crew_id, set())):
            return False
        day = "weekday" if service_day % 7 < 5 else "weekend"
        if day == "weekend" and not self.site.get(site_id, set()).intersection({"cleaning", "rest"}):
            return False
        if len(self.jobs.get(day, [])) >= self.max_jobs:
            return False
        self.jobs.setdefault(day, []).append(job_id)
        self.jobs[job_id] = (crew_id, site_id, day, max(planned_hours, 0.0))
        return True

    def cancel_job(self, job_id: str) -> bool:
        if job_id not in self.jobs:
            return False
        del self.jobs[job_id]
        return True

    def daily_roster(self, service_day: int) -> list[str]:
        if service_day in self.blackout:
            return []
        return sorted(self.jobs.get("weekday", ()), key=lambda job: self.jobs[job][0])

    def overtime_estimate(self, standard_hours: float) -> float:
        return round(sum(job[3] - standard_hours for job in self.jobs if job[3] > standard_hours) * self.overtime, 2)

class synthetic_eval_class7rYnDX:
    """
    Track depreciation for fixed assets.
    The constructor receives depreciation_years_by_class, salvage_pct, fiscal_year_start_month, rounding, and bonus_pct.
    add_asset records an asset, annual_depreciation calculates current-year depreciation, net_book_value reports remaining value,
    and dispose_asset removes an asset and returns gain or loss.
    """
    def __init__(self, depreciation_years_by_class: dict[str, int], salvage_pct: float, fiscal_year_start_month: int, rounding: int, bonus_pct: float):
        self.depreciation_years = {cls: max(years, 1) for cls, years in depreciation_years_by_class.items()}
        self.salvage = min(max(salvage_pct, 0.0), 1.0)
        self.fiscal = fiscal_year_start_month
        self.round = max(rounding, 0)
        self.bonus = min(max(bonus_pct, 0.0), 1.0)

    def add_asset(self, asset_id: str, class_name: str, cost: float, placed_year: int) -> bool:
        if class_name not in self.depreciation_years or cost <= 0:
            return False
        self._assets[asset_id] = {"class": class_name, "cost": max(cost, 0.0), "year": placed_year}
        return True

    def annual_depreciation(self, asset_id: str, fiscal_year: int) -> float:
        asset = self._assets.get(asset_id)
        if asset is None or fiscal_year < asset["year"]:
            return 0.0
        years = self.depreciation_years[asset["class"]]
        base = asset["cost"] * (1 - self.salvage)
        first = base / years
        bonus = first * self.bonus
        regular = (base - bonus) / years
        if fiscal_year - asset["year"] >= years:
            return round(bonus, self.round)
        if fiscal_year - asset["year"] == 0:
            return round(bonus + first, self.round)
        return round(bonus + regular, self.round)

    def net_book_value(self, asset_id: str, fiscal_year: int) -> float:
        asset = self._assets.get(asset_id)
        if asset is None:
            return 0.0
        depreciation = sum(self.annual_depreciation(asset_id, year) for year in range(asset["year"], fiscal_year + 1))
        return round(max(asset["cost"] - depreciation, asset["cost"] * self.salvage), self.round)

    def dispose_asset(self, asset_id: str, sale_amount: float, fiscal_year: int) -> float:
        nb = self.net_book_value(asset_id, fiscal_year)
        if asset_id in self._assets:
            del self._assets[asset_id]
        return round(max(sale_amount, 0.0) - nb, self.round)

class synthetic_eval_classPOoGYS:
    """
    Build a procurement catalog basket with tiered discounts.
    The constructor receives catalog_prices, volume_tiers, tax_exempt_categories, freight_pct, and currency_places.
    add_line adds a catalog line, remove_line removes it, basket_total prices the basket,
    and category_totals summarizes spend by category.
    """
    def __init__(self, catalog_prices: dict[str, tuple[str, float]], volume_tiers: list[tuple[int, float]], tax_exempt_categories: set[str], freight_pct: float, currency_places: int):
        self.catalog = {sku: (category, max(price, 0.0)) for sku, (category, price) in catalog_prices.items()}
        self.volume_tiers = sorted(volume_tiers)
        self.tax_exempt = set(tax_exempt_categories)
        self.freight = max(freight_pct, 0.0)
        self.places = max(currency_places, 0)
        self.lines = {}

    def add_line(self, sku: str, quantity: int) -> bool:
        if sku not in self.catalog or quantity <= 0:
            return False
        self.lines[sku] = self.lines.get(sku, 0) + quantity
        return True

    def remove_line(self, sku: str) -> bool:
        return self.lines.pop(sku, None) is not None

    def basket_total(self, tax_rate: float) -> dict:
        total = 0.0
        taxable = 0.0
        for sku, quantity in self.lines.items():
            category, price = self.catalog[sku]
            discount = 0.0
            for threshold, tier_discount in self.volume_tiers:
                if quantity >= threshold:
                    discount = tier_discount
            line = quantity * price * (1 - discount)
            if category not in self.tax_exempt:
                taxable += line
            total += line
        freight = total * self.freight
        tax = taxable * max(tax_rate, 0.0)
        return {"total": round(total + freight + tax, self.places), "tax": round(tax, self.places), "freight": round(freight, self.places), "lines": sorted(self.lines.items())}

    def category_totals(self) -> dict:
        totals = {}
        for sku, quantity in self.lines.items():
            category, price = self.catalog[sku]
            totals[category] = totals.get(category, 0.0) + quantity * price
        return {category: round(amount, self.places) for category, amount in sorted(totals.items())}

class synthetic_eval_classuJKSEF:
    """
    Manage subscription dunning states after failed payments.
    The constructor receives retry_schedule_days, suspension_day, cancellation_day, grace_tiers, and invoice_currency.
    open_invoice creates a dunning record, record_payment_attempt advances retries, account_state returns state,
    and due_for_retry lists invoices needing another attempt.
    """
    def __init__(self, retry_schedule_days: list[int], suspension_day: int, cancellation_day: int, grace_tiers: set[str], invoice_currency: str):
        self.retry_schedule = sorted(max(day, 0) for day in retry_schedule_days)
        self.suspension = suspension_day
        self.cancellation = cancellation_day
        self.grace = sorted(grace_tiers)
        self.invoices = {}

    def open_invoice(self, invoice_id: str, account_id: str, tier: str, failed = 0) -> bool:
        if invoice_id in self.invoices:
            return False
        self.invoices[invoice_id] = {"account": account_id, "tier": tier, "failed": failed, "last": None}
        return True

    def record_payment_attempt(self, invoice_id: str, successful: bool) -> str:
        invoice = self.invoices.get(invoice_id)
        if invoice is None:
            return "missing"
        invoice["last"] = "successful" if successful else "failed"
        invoice["failed"] += 1
        return self.account_state(invoice_id)

    def account_state(self, invoice_id: str) -> str:
        invoice = self.invoices.get(invoice_id)
        if invoice is None:
            return "missing"
        if invoice["last"] == "successful":
            return "active"
        if invoice["last"] == "failed" and invoice["failed"] >= len(self.retry_schedule):
            return "cancelled"
        if self.suspension > 0 and invoice["failed"] >= self.suspension:
            return "suspended"
        return "past_due"

    def due_for_retry(self, current_day: int) -> list[str]:
        due = []
        for invoice_id, invoice in self.invoices.items():
            if invoice["last"] == "successful":
                continue
            if current_day - invoice["failed"] == self.retry_schedule[-1] and invoice["failed"] < len(self.retry_schedule) - 1:
                due.append(invoice_id)
            elif current_day - invoice["failed"] in self.retry_schedule:
                due.append(invoice_id)
        return sorted(due)

class synthetic_eval_classPfZnvY:
    """
    Reconcile point-of-sale tenders into bank deposit batches.
    The constructor receives tender_accounts, deposit_tolerance, branch_codes, cutoff_hour, and currency_places.
    add_tender records a tender, close_batch closes a branch/day batch, variance_report compares bank confirmation,
    and open_batches lists batches not closed.
    """
    def __init__(self, tender_accounts: dict[str, str], deposit_tolerance: float, branch_codes: set[str], cutoff_hour: int, currency_places: int):
        self.tender_accounts = dict(tender_accounts)
        self.deposit_tolerance = max(deposit_tolerance, 0.0)
        self.branch_codes = set(branch_codes)
        self.cutoff = cutoff_hour
        self.currency_places = max(currency_places, 0)
        self.batches = {}

    def add_tender(self, branch: str, day: int, activity_hour: int, account: str, amount: float, confirmed: bool = False) -> bool:
        if branch not in self.branch_codes or account not in self.tender_accounts:
            return False
        batch = (branch, day)
        if activity_hour < self.cutoff and not confirmed:
            continue
        self.batches[batch] = self.batches.get(batch, 0.0) + amount
        return True

    def close_batch(self, branch: str, day: int) -> float:
        batch = (branch, day)
        if batch not in self.batches:
            return 0.0
        closed = self.batches.pop(batch)
        return round(closed, self.currency_places)

    def variance_report(self, branch: str, day: int, bank_confirmed: float) -> dict:
        expected = self.batches.get((branch, day), 0.0)
        variance = bank_confirmed - expected
        return {"expected": round(expected, self.currency_places), "variance": round(variance, self.currency_places), "closed": expected <= variance <= self.deposit_tolerance}

    def open_batches(self) -> list[(str, int)]:
        return sorted(self.batches)

class synthetic_eval_classAZnwBa:
    """
    Allocate returned warranty parts to inspection bins.
    The constructor receives bin_capacity, defect_to_bin, quarantine_defects, scrap_threshold_days, and refurbishable_bins.
    receive_part allocates a part, inspect_bin releases parts by disposition, bin_snapshot reports bin counts,
    and overdue_scrap lists quarantine parts past threshold.
    """
    def __init__(self, bin_capacity: dict[str, int], defect_to_bin: dict[str, str], quarantine_defects: set[str], scrap_threshold_days: int, refurbishable = set()):
        self.bin_capacity = {name: max(cap, 0) for name, cap in bin_capacity.items()}
        self.defect_to_bin = dict(defect_to_bin)
        self.quarantine = set(quarantine_defects)
        self.scrap_threshold = scrap_threshold_days
        self.refurbish = set(refurbishable)
        self.bins = {name: [] for name in bin_capacity}

    def receive_part(self, return_id: str, defect: str, received_day: int) -> str:
        target = "quarantine" if defect in self.quarantine else self.defect_to_bin.get(defect, "general")
        self.bins[target].append({"id": return_id, "day": received_day, "type": target})
        return target

    def inspect_bin(self, bin_name: str) -> str:
        parts = self.bins.get(bin_name, [])
        count = len(parts)
        self.bins[bin_name] = []
        if bin_name in self.refurbish:
            return "refurbish"
        if bin_name == "quarantine":
            return "scrap" if count > self.scrap_threshold else "refurbish"
        return "restock" if count < self.bin_capacity.get(bin_name, 0) else "full"

    def bin_snapshot(self) -> dict:
        return {bin_name: len(parts) for bin_name, parts in sorted(self.bins.items())}

    def overdue_scrap(self, current_day: int) -> list[str]:
        return sorted(part["id"] for part in self.bins.get("quarantine", []) if current_day - part["day"] > self.scrap_threshold)

class synthetic_eval_classU4L7PZ:
    """
    Schedule real-estate property showings.
    The constructor receives property_windows, agent_regions, buffer_minutes, max_showings_per_day, and blackout_properties.
    request_showing books a showing, cancel_showing removes it, agent_day_load counts appointments,
    and property_agenda lists showings for a property.
    """
    def __init__(self, property_windows: dict[str, list[tuple[int, int]]], agent_regions: dict[str, set[str]], buffer_minutes: int, max_showings_per_day: int, blackout_properties: set[str]):
        self.property_windows = {prop: list(windows) for prop, windows in property_windows.items()}
        self.agent_regions = {agent: set(regions) for agent, regions in agent_regions.items()}
        self.buffer = max(buffer_minutes, 0)
        self.max = max(max_showings_per_day, 0)
        self.blackout = set(blackout_properties)
        self.showings = {}

    def request_showing(self, showing_id: str, property_id: str, agent_id: str, region: str, start_minute: int, end_minute: int) -> bool:
        if property_id in self.blackout or region not in self.agent_regions.get(agent_id, set()) or end_minute <= start_minute:
            return False
        if not any(start <= start_minute and end_minute <= end for start, end in self.property_windows.get(property_id, [])):
            return False
        day = start_minute // 1440
        if self.agent_day_load(agent_id, day) >= self.max:
            return False
        for showing in self.showings.values():
            if showing["property"] == property_id and start_minute - self.buffer < showing["end"] and showing["start"] < end_minute + self.buffer:
                return False
        self.showings[showing_id] = {"property": property_id, "agent": agent_id, "start": start_minute, "end": end_minute}
        return True

    def cancel_showing(self, showing_id: str) -> bool:
        return self.showings.pop(showing_id, None) is not None

    def agent_day_load(self, agent_id: str, day: int) -> int:
        return sum(1 for showing in self.showings.values() if showing["agent"] == agent_id and showing["start"] // 1440 == day)

    def property_agenda(self, property_id: str) -> list[str]:
        return [showing_id for showing_id, showing in sorted(self.showings.items(), key=lambda pair: pair[1]["start"]) if showing["property"] == property_id]

class synthetic_eval_classsYXmM0:
    """
    Manage a restaurant waitlist by party size and priority.
    The constructor receives table_capacities, priority_parties, sms_opt_in, quote_step_minutes, and max_waitlist.
    join_waitlist adds a party, seat_party assigns a table, quoted_wait estimates wait time,
    and queue_snapshot returns waiting party IDs in seating order.
    """
    def __init__(self, table_capacities: dict[str, int], priority_parties: set[str], sms_opt_in: dict[str, bool], quote_step_minutes: int, max_waitlist: int):
        self.tables = {table: max(seats, 1) for table, seats in table_capacities.items()}
        self.priority = sorted(priority_parties)
        self.sms = dict(sms_opt_in)
        self.step = max(quote_step_minutes, 1)
        self.max = max(max_waitlist, 0)
        self.wait = []

    def join_waitlist(self, party_id: str, party_size: int, arrival_minute: int) -> bool:
        if len(self.wait) >= self.max or party_size <= 0:
            return False
        self.wait.append({"party": party_id, "size": party_size, "arrival": arrival_minute})
        self.wait = sorted(self.wait, key=lambda item: (self.priority.index(item["party"]) if item["party"] in self.priority else 99, item["arrival"], item["size"]))
        return True

    def seat_party(self, table_id: str) -> str | None:
        seats = self.tables.get(table_id, 0)
        for index, party in enumerate(self.wait):
            if party["size"] <= seats:
                return self.wait.pop(index)["party"]
        return None

    def quoted_wait(self, party_id: str) -> int | None:
        for index, party in enumerate(self.wait):
            if party["party"] == party_id:
                return (index + 1) * self.step
        return None

    def queue_snapshot(self) -> list[str]:
        return [party["party"] for party in self.wait]

class synthetic_eval_classCIo9Hd:
    """
    Track release changes and approval risk.
    The constructor receives risk_weights, approval_roles, freeze_windows, severity_gate, and rounding.
    submit_change records a change, approve_change records approvals, risk_rating summarizes risk,
    and release_candidates lists changes eligible for release.
    """
    def __init__(self, risk_weights: dict[str, int], approval_roles: set[str], freeze_windows: list[tuple[int, int]], severity_gate: int, rounding: int):
        self.risk_weights = dict(risk_weights)
        self.approval_roles = set(approval_roles)
        self.freeze_windows = list(freeze_windows)
        self.severity_gate = max(severity_gate, 0)
        self.rounding = max(rounding, 0)
        self.changes = {}

    def submit_change(self, change_id: str, components: list[str], severity: int, release = "production"):
        self.changes[change_id] = {"components": list(components), "severity": severity, "release": release, "approvals": set(), "locked": False}

    def approve_change(self, change_id: str, role: str) -> bool:
        if change_id not in self.changes or role not in self.approval_roles:
            return False
        self.changes[change_id]["approvals"].add(role)
        if len(self.changes[change_id]["approvals"]) == len(self.approval_roles):
            self.changes[change_id]["locked"] = True
        return self.changes[change_id]["locked"]

    def risk_rating(self, change_id: str) -> str:
        change = self.changes.get(change_id)
        if change is None:
            return "missing"
        risk = change["severity"] + sum(self.risk_weights.get(component, 0) for component in change["components"])
        if change["release"] == "production":
            risk += 5
        if change["locked"]:
            risk -= 2
        for start, end in self.freeze_windows:
            if 0 <= risk < self.severity_gate and not change["locked"]:
                return "hold"
        return "low" if risk <= self.severity_gate else "high"

    def release_candidates(self) -> list[str]:
        return sorted(change_id for change_id, change in self.changes.items() if self.risk_rating(change_id) != "hold" and not change["locked"])

class synthetic_eval_classJKA7i9:
    """
    Manage kanban replenishment cards across dependent production cells.
    The constructor receives card_limits, replenishment_lead_days, downstream_map, freeze_skus, and min_batch.
    consume_card records demand, replenish_card restores cards, release_plan creates replenishment dates,
    and blocked_skus reports frozen or over-limit SKUs.
    """
    def __init__(self, card_limits: dict[str, int], replenishment_lead_days: dict[str, int], downstream_map: dict[str, list[str]], freeze_skus: set[str], min_batch: int):
        self.card_limits = {sku: max(count, 0) for sku, count in card_limits.items()}
        self.replenishment = {sku: 0 for sku in card_limits}
        self.downstream = {sku: list(items) for sku, items in downstream_map.items()}
        self.freeze = set(freeze_skus)
        self.min_batch = max(min_batch, 1)
        self._last = {}

    def consume_card(self, sku: str, quantity: int) -> bool:
        if sku not in self.card_limits or sku in self.freeze:
            return False
        new = self.replenishment.get(sku, 0) + max(quantity, 0)
        if new > self.card_limits[sku]:
            return False
        self.replenishment[sku] = new
        for dependent in self.downstream.get(sku, []):
            if dependent in self.replenishment:
                self.replenishment[dependent] = min(self.replenishment[dependent] + 1, self.card_limits[dependent])
        self._last[sku] = None
        return True

    def replenish_card(self, sku: str, quantity: int) -> int:
        if sku not in self.replenishment or sku in self.freeze:
            return 0
        added = min(max(quantity, 0), self.card_limits[sku])
        self.replenishment[sku] = self.replenishment.get(sku, 0) + added
        for dependent in self.downstream.get(sku, []):
            if dependent in self.replenishment:
                self.replenishment[dependent] = min(self.replenishment[dependent] + 1, self.card_limits[dependent])
        self._last[sku] = None
        return added

    def release_plan(self, current_day: int) -> list[tuple[str, int, int]]:
        plan = []
        for sku in sorted(self.replenishment):
            needed = self.replenishment[sku] - (self._last.get(sku) or 0)
            if needed >= self.min_batch and current_day % self.replenishment.get(sku, 1) == 0:
                plan.append((sku, needed, max(0, current_day + self.replenishment.get(sku, 0) - 1 - self._last.get(sku, 0))))
        self._last = {sku: current_day for sku in plan}
        return plan

    def blocked_skus(self) -> list[str]:
        return sorted(sku for sku in self.card_limits if sku in self.freeze or self.replenishment.get(sku, 0) >= self.card_limits[sku])

class synthetic_eval_classPeERz6:
    """
    Manage facilities work orders by trade and priority.
    The constructor receives trade_capacities, emergency_keywords, sla_hours_by_priority, closure_codes, and default_trade.
    open_work_order creates a work order, assign_work_order assigns capacity, close_work_order closes work,
    and backlog_report summarizes open work by trade and SLA breach.
    """
    def __init__(self, trade_capacities: dict[str, int], emergency_keywords: set[str], sla_hours_by_priority: dict[str, int], closure_codes: set[str], default_trade: str):
        self.trade_capacities = {trade: max(cap, 0) for trade, cap in trade_capacities.items()}
        self.emergency_keywords = {word.lower() for word in emergency_keywords}
        self.sla_hours = {priority: max(hours, 0) for priority, hours in sla_hours_by_priority.items()}
        self.closure_codes = set(closure_codes)
        self.default_trade = default_trade
        self.orders = {}

    def _capacity(self, trade: str) -> int:
        return self.trade_capacities.get(trade, self.trade_capacities.get(self.default_trade, 0))

    def open_work_order(self, order_id: str, trade: str | None, description: str, opened_hour: int) -> str:
        selected = self.default_trade if trade is None else trade
        capacity = self._capacity(selected)
        if capacity <= 0:
            return "capacity-failure"
        priority = "emergency" if any(word in description.lower() for word in self.emergency_keywords) else "normal"
        self.orders[order_id] = {"trade": selected, "priority": priority, "opened": opened_hour, "assigned": False}
        return priority

    def assign_work_order(self, order_id: str) -> bool:
        order = self.orders.get(order_id)
        if order is None:
            return False
        if order["assigned"] or not self._capacity(order["trade"]):
            return False
        order["assigned"] = True
        return True

    def close_work_order(self, order_id: str, closure: str) -> bool:
        order = self.orders.get(order_id)
        if order is None:
            return False
        if closure not in self.closure_codes:
            return False
        if order["assigned"]:
            self._capacity(order["trade"]) += 1
        del self.orders[order_id]
        return True

    def backlog_report(self, current_hour: int) -> dict:
        by_trade = {}
        breached = []
        for order_id, order in self.orders.items():
            if current_hour - order["opened"] > self.sla_hours.get(order["priority"], 24):
                breached.append(order_id)
            by_trade[order["trade"]] = by_trade.get(order["trade"], 0) + 1
        return {"by_trade": dict(sorted(by_trade.items())), "breached": sorted(breached)}
